import React, { useState, useEffect } from 'react';
import { 
  Play, FlaskConical, Check, X, Info, 
  TrendingUp, BarChart3, History, Layers
} from 'lucide-react';
import { api } from '../api/client';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, 
  Tooltip, ResponsiveContainer, AreaChart, Area
} from 'recharts';

const STRATEGIES = [
  { id: 'use_zscore', label: 'Z-Score', description: 'Price deviation from rolling mean' },
  { id: 'use_rsi', label: 'RSI', description: 'Relative Strength Index momentum' },
  { id: 'use_bb', label: 'Bollinger Bands', description: 'Volatility envelope breach' },
  { id: 'use_vwap', label: 'VWAP', description: 'Volume Weighted Average Price' },
  { id: 'use_stoch', label: 'Stochastic', description: 'Momentum exhaustion' },
  { id: 'use_lsl', label: 'LSL Grab', description: 'Liquidity Sweep Levels' },
  { id: 'use_smc', label: 'SMC Structure', description: 'BOS/CHoCH & Order Blocks' },
  { id: 'use_volume', label: 'Volume Spike', description: 'Unusual volume activity' },
  { id: 'use_hurst', label: 'Hurst Regime', description: 'Mean-reversion vs Trending' },
];

const SYMBOLS = ['R_10', 'R_25', 'R_50', 'R_75', 'R_100', '1HZ10V', '1HZ25V', '1HZ50V', '1HZ75V', '1HZ100V'];

export default function Backtest() {
  const [selectedStrategies, setSelectedStrategies] = useState<Record<string, boolean>>({
    use_zscore: true, use_rsi: true, use_bb: true, use_vwap: true,
    use_stoch: true, use_lsl: true, use_smc: true, use_volume: true, use_hurst: true
  });
  const [selectedSymbols, setSelectedSymbols] = useState<string[]>(['R_75']);
  const [timeframe, setTimeframe] = useState('M5');
  const [days, setDays] = useState(7);
  const [minConfluence, setMinConfluence] = useState(6);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<any[]>([]);
  const [recentRuns, setRecentRuns] = useState<any[]>([]);

  useEffect(() => {
    fetchRecentRuns();
  }, []);

  const fetchRecentRuns = async () => {
    try {
      const data = await api.get('/api/backtest/results') as any[];
      setRecentRuns(data);
    } catch (err) {
      console.error('Failed to fetch recent runs', err);
    }
  };

  const toggleStrategy = (id: string) => {
    setSelectedStrategies(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const toggleSymbol = (symbol: string) => {
    setSelectedSymbols(prev => 
      prev.includes(symbol) ? prev.filter(s => s !== symbol) : [...prev, symbol]
    );
  };

  const runBacktest = async () => {
    if (selectedSymbols.length === 0) return;
    setLoading(true);
    try {
      const payload = {
        symbols: selectedSymbols,
        timeframe,
        days,
        min_confluence: minConfluence,
        ...selectedStrategies
      };
      const data = await api.post('/api/backtest/run', payload) as any[];
      setResults(data);
      fetchRecentRuns();
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unknown error'
      alert(`Backtest failed: ${message}`)
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-2">
            <FlaskConical className="text-cyan-400" />
            Strategy Lab
          </h1>
          <p className="text-slate-400 text-sm mt-1">
            Test combinations of strategies against historical data to identify optimal setups.
          </p>
        </div>
        <button
          onClick={runBacktest}
          disabled={loading || selectedSymbols.length === 0}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-lg font-semibold transition-all ${
            loading || selectedSymbols.length === 0
              ? 'bg-slate-700 text-slate-500 cursor-not-allowed'
              : 'bg-cyan-500 hover:bg-cyan-400 text-slate-900 shadow-lg shadow-cyan-500/20'
          }`}
        >
          {loading ? (
            <div className="w-5 h-5 border-2 border-slate-900 border-t-transparent rounded-full animate-spin" />
          ) : (
            <Play className="w-5 h-5 fill-current" />
          )}
          {loading ? 'Running Test...' : 'Run Combined Test'}
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Sidebar: Controls */}
        <div className="space-y-6">
          {/* Strategies */}
          <div className="bg-slate-800 border border-slate-700 rounded-xl p-5 shadow-sm">
            <h2 className="text-sm font-bold text-slate-300 uppercase tracking-wider mb-4 flex items-center gap-2">
              <Layers className="w-4 h-4 text-cyan-400" />
              Active Strategies
            </h2>
            <div className="grid grid-cols-1 gap-2">
              {STRATEGIES.map(s => (
                <button
                  key={s.id}
                  onClick={() => toggleStrategy(s.id)}
                  className={`flex items-center justify-between px-3 py-2.5 rounded-lg border transition-all text-left group ${
                    selectedStrategies[s.id]
                      ? 'bg-cyan-500/10 border-cyan-500/30 text-cyan-400'
                      : 'bg-slate-900/50 border-slate-700 text-slate-500 hover:border-slate-600'
                  }`}
                >
                  <div>
                    <div className="text-sm font-medium">{s.label}</div>
                    <div className="text-[10px] opacity-60 leading-tight mt-0.5">{s.description}</div>
                  </div>
                  {selectedStrategies[s.id] ? (
                    <Check className="w-4 h-4 flex-shrink-0" />
                  ) : (
                    <X className="w-4 h-4 flex-shrink-0 opacity-20 group-hover:opacity-100" />
                  )}
                </button>
              ))}
            </div>
          </div>

          {/* Symbols */}
          <div className="bg-slate-800 border border-slate-700 rounded-xl p-5 shadow-sm">
            <h2 className="text-sm font-bold text-slate-300 uppercase tracking-wider mb-4 flex items-center gap-2">
              <TrendingUp className="w-4 h-4 text-cyan-400" />
              Assets to Include
            </h2>
            <div className="flex flex-wrap gap-2">
              {SYMBOLS.map(symbol => (
                <button
                  key={symbol}
                  onClick={() => toggleSymbol(symbol)}
                  className={`px-3 py-1.5 rounded-md text-xs font-semibold border transition-all ${
                    selectedSymbols.includes(symbol)
                      ? 'bg-cyan-500 border-cyan-500 text-slate-900'
                      : 'bg-slate-900/50 border-slate-700 text-slate-400 hover:border-slate-600'
                  }`}
                >
                  {symbol}
                </button>
              ))}
            </div>
          </div>

          {/* Parameters */}
          <div className="bg-slate-800 border border-slate-700 rounded-xl p-5 shadow-sm space-y-4">
            <h2 className="text-sm font-bold text-slate-300 uppercase tracking-wider mb-2">Parameters</h2>
            <div>
              <label className="text-xs text-slate-500 block mb-1.5">Lookback (Days)</label>
              <select 
                value={days} 
                onChange={e => setDays(Number(e.target.value))}
                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-200 outline-none focus:border-cyan-500"
              >
                <option value={1}>1 Day</option>
                <option value={7}>7 Days</option>
                <option value={30}>30 Days</option>
                <option value={90}>90 Days</option>
              </select>
            </div>
            <div>
              <label className="text-xs text-slate-500 block mb-1.5">Min. Confluence Score ({minConfluence})</label>
              <input 
                type="range" min="4" max="12" step="1"
                value={minConfluence}
                onChange={e => setMinConfluence(Number(e.target.value))}
                className="w-full accent-cyan-500"
              />
            </div>
          </div>
        </div>

        {/* Main Result Area */}
        <div className="lg:col-span-2 space-y-6">
          {results.length > 0 ? (
            results.map((res, idx) => (
              <div key={idx} className="bg-slate-800 border border-slate-700 rounded-xl overflow-hidden shadow-sm">
                <div className="p-5 border-b border-slate-700 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-cyan-500/20 flex items-center justify-center">
                      <BarChart3 className="w-6 h-6 text-cyan-400" />
                    </div>
                    <div>
                      <h3 className="font-bold text-white text-lg">{res.symbol} Analysis</h3>
                      <p className="text-xs text-slate-500">Backtest Period: {days} days · Timeframe: {timeframe}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-xs text-slate-500 uppercase tracking-widest font-bold">Sharpe Ratio</div>
                    <div className={`text-2xl font-black ${res.sharpe_ratio > 1 ? 'text-green-400' : 'text-yellow-400'}`}>
                      {res.sharpe_ratio.toFixed(2)}
                    </div>
                  </div>
                </div>

                {/* Stats Grid */}
                <div className="grid grid-cols-2 md:grid-cols-4 border-b border-slate-700">
                  <div className="p-4 border-r border-slate-700">
                    <div className="text-[10px] text-slate-500 uppercase font-bold mb-1">Total P&L</div>
                    <div className={`text-lg font-bold ${res.total_pnl >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                      {res.total_pnl >= 0 ? '+' : ''}{res.total_pnl.toFixed(2)} ({res.total_pnl_pct.toFixed(1)}%)
                    </div>
                  </div>
                  <div className="p-4 border-r border-slate-700">
                    <div className="text-[10px] text-slate-500 uppercase font-bold mb-1">Win Rate</div>
                    <div className="text-lg font-bold text-white">{(res.win_rate * 100).toFixed(1)}%</div>
                  </div>
                  <div className="p-4 border-r border-slate-700">
                    <div className="text-[10px] text-slate-500 uppercase font-bold mb-1">Trades</div>
                    <div className="text-lg font-bold text-white">{res.total_trades}</div>
                  </div>
                  <div className="p-4">
                    <div className="text-[10px] text-slate-500 uppercase font-bold mb-1">Max DD</div>
                    <div className="text-lg font-bold text-red-400">{(res.max_drawdown * 100).toFixed(1)}%</div>
                  </div>
                </div>

                {/* Chart Area */}
                <div className="h-64 p-5">
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={res.equity_curve}>
                      <defs>
                        <linearGradient id="colorBalance" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="#06b6d4" stopOpacity={0.3}/>
                          <stop offset="95%" stopColor="#06b6d4" stopOpacity={0}/>
                        </linearGradient>
                      </defs>
                      <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                      <XAxis dataKey="ts" hide />
                      <YAxis 
                        hide 
                        domain={['dataMin - 100', 'dataMax + 100']}
                      />
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }}
                        itemStyle={{ color: '#22d3ee' }}
                      />
                      <Area 
                        type="monotone" 
                        dataKey="balance" 
                        stroke="#06b6d4" 
                        fillOpacity={1} 
                        fill="url(#colorBalance)" 
                        strokeWidth={2}
                      />
                    </AreaChart>
                  </ResponsiveContainer>
                </div>
              </div>
            ))
          ) : (
            <div className="bg-slate-800/50 border-2 border-dashed border-slate-700 rounded-2xl flex flex-col items-center justify-center p-20 text-center">
              <FlaskConical className="w-16 h-16 text-slate-600 mb-4" />
              <h3 className="text-xl font-bold text-slate-400">Ready to Experiment</h3>
              <p className="text-slate-500 max-w-sm mt-2">
                Select your strategies and pairs on the left, then run a combined test to see the performance report.
              </p>
            </div>
          )}

          {/* Recent Runs */}
          <div className="bg-slate-800 border border-slate-700 rounded-xl overflow-hidden shadow-sm">
            <div className="p-4 border-b border-slate-700 flex items-center gap-2">
              <History className="w-4 h-4 text-slate-400" />
              <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider">Recent Experiments</h3>
            </div>
            <div className="divide-y divide-slate-700">
              {recentRuns.length > 0 ? (
                recentRuns.map((run, i) => (
                  <div key={i} className="px-5 py-3 flex items-center justify-between hover:bg-slate-700/30 transition-colors">
                    <div className="flex items-center gap-4">
                      <span className="text-xs font-mono text-slate-500">#{run.run_id}</span>
                      <div>
                        <div className="text-sm font-bold text-white">{run.symbol}</div>
                        <div className="text-[10px] text-slate-500">{new Date(run.run_at).toLocaleString()}</div>
                      </div>
                    </div>
                    <div className="flex items-center gap-6">
                      <div className="text-right">
                        <div className="text-[10px] text-slate-500 uppercase font-bold">Sharpe</div>
                        <div className="text-sm font-bold text-cyan-400">{run.sharpe_ratio?.toFixed(2)}</div>
                      </div>
                      <div className="text-right">
                        <div className="text-[10px] text-slate-500 uppercase font-bold">P&L</div>
                        <div className={`text-sm font-bold ${run.total_pnl >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                          {run.total_pnl >= 0 ? '+' : ''}{run.total_pnl?.toFixed(1)}%
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="p-8 text-center text-slate-500 text-sm italic">No recent experiments found.</div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * pages/Dashboard.tsx
 * ─────────────────────────────────────────────────────────────────────────────
 * Main trading dashboard — real-time bot status, equity curve,
 * open positions, live signal feed, circuit breaker panel.
 *
 * Polls the API every 5s for updates. A production build would
 * upgrade this to a WebSocket connection (/ws/live).
 * ─────────────────────────────────────────────────────────────────────────────
 */

import { useEffect, useState, useCallback, useMemo } from 'react'
import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer,
} from 'recharts'
import { format } from 'date-fns'
import {
  Activity, TrendingUp, TrendingDown, AlertTriangle,
  StopCircle, PlayCircle, RefreshCw, Zap, Shield,
} from 'lucide-react'
import {
  fetchBotStatus, fetchRisk, fetchSignals, fetchTrades,
  fetchBotPerformance,
  stopBot, startBot, resetCircuitBreaker,
  type BotStatus, type RiskDashboard, type Signal, type Trade,
} from '../api/client'

// ── Types ─────────────────────────────────────────────────────────────────────

interface DashState {
  status:   BotStatus | null
  risk:     RiskDashboard | null
  signals:  Signal[]
  trades:   Trade[]
  performance: any | null
  loading:  boolean
  error:    string | null
  lastRefresh: Date | null
}

// ── Helpers ───────────────────────────────────────────────────────────────────

const pnlColor  = (v: number) => v >= 0 ? 'text-emerald-400' : 'text-red-400'
const dirColor  = (d: string) => d === 'buy' ? 'text-emerald-400' : 'text-red-400'
const dirBg     = (d: string) => d === 'buy' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'
const scoreColor = (s: number) => s >= 9 ? 'text-yellow-400' : s >= 6 ? 'text-emerald-400' : 'text-slate-400'
const cbColor   = (state: string) => ({
  active:   'text-emerald-400 bg-emerald-500/10',
  paused:   'text-yellow-400 bg-yellow-500/10',
  halted:   'text-red-400 bg-red-500/10',
  cooldown: 'text-orange-400 bg-orange-500/10',
}[state] ?? 'text-slate-400 bg-slate-500/10')

function fmt(ts: string) {
  try { return format(new Date(ts), 'HH:mm:ss') } catch { return ts }
}

// ── Stat Card ─────────────────────────────────────────────────────────────────

function StatCard({ label, value, sub, accent = false }: {
  label: string; value: string; sub?: string; accent?: boolean
}) {
  return (
    <div className="bg-slate-800 border border-slate-700 rounded-xl p-3 sm:p-4">
      <p className="text-[10px] sm:text-xs text-slate-400 uppercase tracking-wider mb-1">{label}</p>
      <p className={`text-lg sm:text-2xl font-bold ${accent ? 'text-cyan-400' : 'text-white'}`}>{value}</p>
      {sub && <p className="text-[10px] sm:text-xs text-slate-500 mt-1">{sub}</p>}
    </div>
  )
}

// ── Circuit Breaker Badge ─────────────────────────────────────────────────────

function CBBadge({ state }: { state: string }) {
  return (
    <span className={`px-2 py-0.5 rounded-full text-xs font-semibold uppercase ${cbColor(state)}`}>
      {state}
    </span>
  )
}

// ── Main Dashboard ────────────────────────────────────────────────────────────

export default function Dashboard() {
  const [state, setState] = useState<DashState>({
    status: null, risk: null, signals: [], trades: [],
    performance: null,
    loading: true, error: null, lastRefresh: null,
  })
  const [actionLoading, setActionLoading] = useState(false)

  const refresh = useCallback(async () => {
    try {
      const [status, risk, sigRes, tradeRes, perfRes] = await Promise.all([
        fetchBotStatus(),
        fetchRisk(),
        fetchSignals({ limit: 20, fired: true }),
        fetchTrades({ status: 'open', page_size: 10 }),
        fetchBotPerformance(),
      ])
      setState(s => ({
        ...s, status, risk,
        signals: sigRes.signals,
        trades:  tradeRes.trades,
        performance: perfRes.stats,
        loading: false, error: null,
        lastRefresh: new Date(),
      }))
    } catch (err: any) {
      setState(s => ({ ...s, loading: false, error: err.message }))
    }
  }, [])

  // Poll every 5s
  useEffect(() => {
    refresh()
    const id = setInterval(refresh, 5000)
    return () => clearInterval(id)
  }, [refresh])

  const handleStop = async () => {
    setActionLoading(true)
    try { await stopBot(); await refresh() }
    finally { setActionLoading(false) }
  }
  const handleStart = async () => {
    setActionLoading(true)
    try { await startBot(); await refresh() }
    finally { setActionLoading(false) }
  }
  const handleResetCB = async () => {
    if (!confirm('Reset circuit breaker? Only do this if you have reviewed the cause.')) return
    setActionLoading(true)
    try { await resetCircuitBreaker(); await refresh() }
    finally { setActionLoading(false) }
  }

  const { status, risk, signals, trades, loading, error, lastRefresh } = state
  const cbState    = status?.circuit_breaker.state ?? 'unknown'
  const balance    = status?.equity.balance ?? risk?.current_balance ?? null
  const dailyPnl   = status?.equity.daily_pnl ?? risk?.daily_pnl ?? null
  const openTrades = status?.equity.open_trades ?? 0
  const ddPct      = risk?.daily_drawdown_pct ?? 0
  const equityCurve = (risk?.equity_curve ?? []).map(p => ({
    time:    fmt(p.ts),
    balance: p.balance,
  }))

  if (loading) return (
    <div className="flex items-center justify-center h-64">
      <RefreshCw className="animate-spin text-cyan-400 w-8 h-8" />
    </div>
  )

  return (
    <div className="p-6 space-y-6">

      {/* ── Header ─────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white flex items-center gap-2">
            <Zap className="text-cyan-400 w-5 h-5 sm:w-6 sm:h-6" />
            Strategy Tester
          </h1>
          <p className="text-slate-400 text-xs sm:text-sm mt-0.5">
            {lastRefresh ? `Updated ${format(lastRefresh, 'HH:mm:ss')}` : 'Loading...'}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2 sm:gap-3">
          <CBBadge state={cbState} />
          {cbState === 'halted' && (
            <button
              onClick={handleResetCB}
              disabled={actionLoading}
              className="px-2 sm:px-3 py-1 sm:py-1.5 text-[10px] sm:text-xs bg-orange-500/20 text-orange-400 border border-orange-500/30 rounded-lg hover:bg-orange-500/30 transition"
            >
              Reset CB
            </button>
          )}
          <button
            title={status?.bot_running ? "Disable Deriv entries and request managed-position closure" : "Enable entries for the existing Deriv worker; does not start MT5 demo or a backtest"}
            onClick={status?.bot_running ? handleStop : handleStart}
            disabled={actionLoading}
            className={`flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg text-xs sm:text-sm font-medium transition
              ${status?.bot_running
                ? 'bg-red-500/20 text-red-400 border border-red-500/30 hover:bg-red-500/30'
                : 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 hover:bg-emerald-500/30'
              }`}
          >
            {status?.bot_running
              ? <><StopCircle className="w-3 h-3 sm:w-4 sm:h-4" /> Stop Deriv worker</>
              : <><PlayCircle className="w-3 h-3 sm:w-4 sm:h-4" /> Enable Deriv entries</>
            }
          </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/30 rounded-xl p-4 text-red-400 text-sm flex items-center gap-2">
          <AlertTriangle className="w-4 h-4 flex-shrink-0" />
          {error}
        </div>
      )}

      {/* ── Stats Row ──────────────────────────────────────────── */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          label="Account Balance"
          value={balance != null ? `$${balance.toFixed(2)}` : '—'}
          accent
        />
        <StatCard
          label="Daily P&L"
          value={dailyPnl != null ? `$${dailyPnl >= 0 ? '+' : ''}${dailyPnl.toFixed(2)}` : '—'}
          sub={`Daily drawdown: ${ddPct.toFixed(1)}%`}
        />
        <StatCard
          label="Open Positions"
          value={String(openTrades)}
          sub="Max 3 allowed"
        />
        <StatCard
          label="CB State"
          value={cbState.toUpperCase()}
          sub={status?.circuit_breaker.last_trigger?.replace(/_/g, ' ') ?? ''}
        />
      </div>

      {/* ── Phase 6: Advanced Analytics Row ───────────────────── */}
      {state.performance && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard
            label="Win Rate"
            value={`${state.performance.win_rate}%`}
            sub={`${state.performance.total_trades} total trades`}
          />
          <StatCard
            label="Profit Factor"
            value={state.performance.profit_factor?.toFixed(2) ?? '—'}
            sub={`Avg Win: $${state.performance.avg_win}`}
          />
          <StatCard
            label="Sharpe Ratio"
            value={state.performance.sharpe_ratio?.toFixed(2) ?? '—'}
            sub="Requires full equity history"
          />
          <StatCard
            label="Max Drawdown"
            value={state.performance.max_drawdown_pct == null ? '—' : `${state.performance.max_drawdown_pct}%`}
            sub="Requires full equity history"
          />
        </div>
      )}

      {/* ── Equity Curve ───────────────────────────────────────── */}
      {equityCurve.length > 1 && (
        <div className="bg-slate-800 border border-slate-700 rounded-xl p-5">
          <h2 className="text-sm font-semibold text-slate-300 uppercase tracking-wider mb-4 flex items-center gap-2">
            <Activity className="w-4 h-4 text-cyan-400" />
            Equity Curve
          </h2>
          <ResponsiveContainer width="100%" height={180}>
            <AreaChart data={equityCurve} margin={{ top: 4, right: 8, bottom: 0, left: 0 }}>
              <defs>
                <linearGradient id="eqGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%"  stopColor="#06b6d4" stopOpacity={0.25} />
                  <stop offset="95%" stopColor="#06b6d4" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
              <XAxis dataKey="time" tick={{ fill: '#475569', fontSize: 10 }} tickLine={false} />
              <YAxis tick={{ fill: '#475569', fontSize: 10 }} tickLine={false} axisLine={false}
                     tickFormatter={v => `$${v.toFixed(0)}`} width={55} />
              <Tooltip
                contentStyle={{ background: '#0f172a', border: '1px solid #1e293b', borderRadius: 8 }}
                labelStyle={{ color: '#94a3b8', fontSize: 11 }}
                formatter={(v: number) => [`$${v.toFixed(2)}`, 'Balance']}
              />
              <Area type="monotone" dataKey="balance" stroke="#06b6d4" strokeWidth={2}
                    fill="url(#eqGrad)" dot={false} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* ── Bottom Grid: Open Trades + Signal Feed ──────────────── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Open Positions */}
        <div className="bg-slate-800 border border-slate-700 rounded-xl p-5">
          <h2 className="text-sm font-semibold text-slate-300 uppercase tracking-wider mb-4">
            Open Positions
          </h2>
          {trades.length === 0
            ? <p className="text-slate-500 text-sm text-center py-6">No open positions</p>
            : (
              <div className="space-y-3">
                {trades.map(t => (
                  <div key={t.trade_id}
                       className="flex items-center justify-between bg-slate-700/50 rounded-lg px-4 py-3">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className={`text-xs font-bold px-2 py-0.5 rounded ${dirBg(t.direction)}`}>
                          {t.direction.toUpperCase()}
                        </span>
                        <span className="text-sm font-medium text-white">{t.symbol}</span>
                        <span className="text-xs text-slate-400">{t.timeframe}</span>
                      </div>
                      <div className="text-xs text-slate-400 mt-1">
                        Entry {t.entry_price.toFixed(5)} &nbsp;|&nbsp;
                        SL {t.stop_loss.toFixed(5)} &nbsp;|&nbsp;
                        TP {t.take_profit.toFixed(5)}
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-xs text-slate-400">Score</div>
                      <div className={`font-bold ${scoreColor(t.confluence_score)}`}>
                        {t.confluence_score}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )
          }
        </div>

        {/* Signal Feed */}
        <div className="bg-slate-800 border border-slate-700 rounded-xl p-5">
          <h2 className="text-sm font-semibold text-slate-300 uppercase tracking-wider mb-4 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Shield className="w-4 h-4 text-cyan-400" />
              Recent Signal Feed
            </div>
            <span className="text-[10px] text-slate-500 font-normal">REAL-TIME ANALYSIS</span>
          </h2>
          {signals.length === 0
            ? <p className="text-slate-500 text-sm text-center py-6">No signals yet</p>
            : (
              <div className="space-y-3 max-h-[400px] overflow-y-auto pr-1 custom-scrollbar">
                {signals.map(s => (
                  <div key={s.id}
                       className="group bg-slate-700/30 hover:bg-slate-700/50 border border-slate-700/50 rounded-lg p-3 transition-all duration-200">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center gap-2">
                        <div className={`w-1.5 h-1.5 rounded-full ${s.fired ? 'bg-cyan-400 animate-pulse' : 'bg-slate-500'}`} />
                        <span className="font-bold text-white text-sm">{s.symbol}</span>
                        <span className="text-[10px] bg-slate-800 text-slate-400 px-1.5 py-0.5 rounded uppercase tracking-tighter">
                          {s.timeframe}
                        </span>
                        {s.indicators.is_scaling && (
                          <span className="text-[9px] bg-purple-500/20 text-purple-400 px-1.5 py-0.5 rounded border border-purple-500/30 font-bold uppercase">
                            SCALE #{s.indicators.order_index}
                          </span>
                        )}
                      </div>
                      <div className="text-right">
                        <div className={`text-sm font-black ${scoreColor(s.score)}`}>
                          {s.score} <span className="text-[10px] font-normal text-slate-500">pts</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 mb-3">
                      <span className={`flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase ${dirBg(s.direction || '')}`}>
                        {s.direction === 'buy' ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
                        {s.direction}
                      </span>
                      <span className="text-[10px] text-slate-500 italic truncate flex-1">
                        {s.reason.replace(/_/g, ' ')}
                      </span>
                      <span className="text-[10px] text-slate-600 font-mono">{fmt(s.evaluated_at)}</span>
                    </div>

                    {/* Breakdown Chips */}
                    {s.indicators.breakdown && Object.keys(s.indicators.breakdown).length > 0 && (
                      <div className="flex flex-wrap gap-1.5 border-t border-slate-700/50 pt-2 opacity-60 group-hover:opacity-100 transition-opacity">
                        {Object.entries(s.indicators.breakdown).map(([key, val]) => val > 0 && (
                          <div key={key} className="flex items-center gap-1 bg-slate-800/80 px-1.5 py-0.5 rounded text-[9px] border border-slate-700">
                            <span className="text-slate-400 capitalize">{key.replace('_', ' ')}</span>
                            <span className="text-cyan-400 font-bold">+{val}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )
          }
        </div>

      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { api } from '../api/client'
import { usePermissions } from '../auth/identity'
import examples from '../data/institutional-examples.json'

type Revision = { spec_hash: string; instrument_id: string; venue: string; venue_symbol: string; revision: string; registered_at: string }
type Plan = { catalog: Revision; catalog_observed_by_decision: boolean; note: string;
  report: { request: object; report_id: string; result: Record<string, unknown> } }
const { instrument: exampleSpec, ...examplePlan } = examples['instrument-plan'].input

export default function InstrumentCatalog() {
  const { canRunResearch, canRegisterInstrument } = usePermissions()
  const [spec, setSpec] = useState(JSON.stringify(exampleSpec, null, 2))
  const [scenario, setScenario] = useState(JSON.stringify(examplePlan, null, 2))
  const [rows, setRows] = useState<Revision[]>([])
  const [selected, setSelected] = useState<Revision | null>(null)
  const [report, setReport] = useState<Plan | null>(null)
  const [search, setSearch] = useState('')
  const [offset, setOffset] = useState(0)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [message, setMessage] = useState('')
  async function act(action: () => Promise<void>) {
    setBusy(true); setError(''); setMessage('')
    try { await action() } catch (e) { setError(e instanceof Error ? e.message : String(e)) }
    finally { setBusy(false) }
  }
  async function load(page = 0) {
    const query = new URLSearchParams({ q: search, limit: '25', offset: String(page) })
    const data = await api.get(`/api/instruments/revisions?${query}`) as { revisions: Revision[] }
    setRows(data.revisions); setOffset(page)
  }
  useEffect(() => { void act(() => load()) }, [])
  async function select(row: Revision) {
    const data = await api.get(`/api/instruments/revisions/${row.spec_hash}`) as Revision & { spec: object }
    setSelected(row); setSpec(JSON.stringify(data.spec, null, 2)); setReport(null)
  }
  async function register() {
    const row = await api.post('/api/instruments/revisions', JSON.parse(spec)) as Revision
    setSelected(row); setReport(null); await load()
    setMessage('Revision registered. Changes require a new revision identifier.')
  }
  async function plan() {
    setReport(null)
    setReport(await api.post('/api/instruments/plans', { ...JSON.parse(scenario), spec_hash: selected?.spec_hash }) as Plan)
  }
  function download() {
    const url = URL.createObjectURL(new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' }))
    const link = document.createElement('a'); link.href = url; link.download = `instrument-plan-${report?.report.report_id.slice(0, 12)}.json`; link.click()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }
  const editor = 'block w-full mt-2 h-72 p-3 font-mono text-xs bg-slate-950 border border-slate-600 rounded'
  return <div className="p-4 sm:p-6 max-w-6xl space-y-6 min-w-0">
    <header><h1 className="text-2xl font-bold">Instrument catalog</h1><p className="text-slate-400 mt-2">Preserve instrument revisions and build execution plans against their exact rules.</p></header>
    <p className="rounded-lg border border-amber-700/50 bg-amber-950/30 p-4 text-sm text-amber-200">The prefilled specification and book are synthetic. Register provider-verified metadata before using real data. Plans are offline projections and never submit orders.</p>
    <fieldset disabled={busy} className="space-y-6 min-w-0">
      <section className="bg-slate-800 rounded-xl p-5 space-y-3">
        <h2 className="font-semibold text-lg">Stored revisions</h2>
        <div className="flex flex-col sm:flex-row gap-3"><input aria-label="Search instrument ID" placeholder="Search instrument ID" className="min-w-0 flex-1 bg-slate-950 rounded p-2 border border-slate-600" value={search} onChange={e => setSearch(e.target.value)} /><button className="px-4 py-2 bg-slate-700 rounded" onClick={() => void act(() => load())}>Search / refresh</button></div>
        <div className="overflow-auto"><table className="w-full text-left text-sm"><thead className="text-slate-400"><tr><th className="p-2">Instrument</th><th className="p-2">Venue</th><th className="p-2">Revision</th><th className="p-2">Select</th></tr></thead><tbody>
          {rows.map(row => <tr key={row.spec_hash} className="border-t border-slate-700"><td className="p-2">{row.instrument_id}<div className="text-xs text-slate-400">{row.venue_symbol}</div></td><td className="p-2">{row.venue}</td><td className="p-2">{row.revision}</td><td className="p-2"><button onClick={() => void act(() => select(row))} className="text-cyan-300">{selected?.spec_hash === row.spec_hash ? 'Selected' : 'Use revision'}</button></td></tr>)}
        </tbody></table></div>
        {!rows.length && <p className="text-sm text-slate-400">No matching revisions. An administrator can register a specification below.</p>}
        <div className="flex gap-3 text-sm"><button disabled={offset === 0} onClick={() => void act(() => load(Math.max(0, offset - 25)))}>Previous</button><span>Page {offset / 25 + 1}</span><button disabled={rows.length < 25} onClick={() => void act(() => load(offset + 25))}>Next</button></div>
      </section>
      <div className="grid lg:grid-cols-2 gap-5">
        <section className="bg-slate-800 rounded-xl p-5 space-y-3 min-w-0"><h2 className="font-semibold">Register a specification (admin)</h2>
          <p className="text-sm text-slate-400">Publication and validity times, sessions, contract size and grids must come from the provider. Stored revisions cannot be edited or deleted.</p>
          <label className="block text-sm">Specification JSON<textarea aria-label="Instrument specification JSON" className={editor} spellCheck={false} value={spec} onChange={e => setSpec(e.target.value)} /></label>
          <button disabled={!canRegisterInstrument} onClick={() => void act(register)} className="bg-slate-700 px-4 py-2 rounded disabled:opacity-50">Register revision</button>
          {!canRegisterInstrument && <p className="text-sm text-slate-400">Only administrators can register instrument revisions.</p>}
        </section>
        <section className="bg-slate-800 rounded-xl p-5 space-y-3 min-w-0"><h2 className="font-semibold">Plan against selected revision</h2>
          <p className="text-sm text-slate-400">Book quantities use native lots/contracts. Prices use quote currency per underlying unit. The selected stored revision is used; edits in the specification editor do not alter it.</p>
          <p className="text-xs break-all text-cyan-200">{selected ? `Pinned: ${selected.venue_symbol} / ${selected.revision} / ${selected.spec_hash}` : 'Select or register a revision first.'}</p>
          <label className="block text-sm">Order and native book JSON<textarea aria-label="Order planning JSON" className={editor} spellCheck={false} value={scenario} onChange={e => { setScenario(e.target.value); setReport(null) }} /></label>
          <button disabled={!selected || !canRunResearch} onClick={() => void act(plan)} className="bg-cyan-700 px-4 py-2 rounded disabled:opacity-50">Generate offline plan</button>
          {!canRunResearch && <p className="text-sm text-slate-400">Viewer access: browse revisions. Generating plans requires an operator or administrator.</p>}
        </section>
      </div>
    </fieldset>
    {busy && <p role="status" className="text-slate-400">Working...</p>}
    {error && <p role="alert" className="text-red-300 whitespace-pre-wrap break-words text-sm">{error}</p>}
    {message && <p role="status" className="text-cyan-200 text-sm">{message}</p>}
    {report && <section className="bg-slate-800 rounded-xl p-5 space-y-4">
      <div className="flex justify-between flex-wrap gap-3"><h2 className="font-semibold text-lg">Instrument execution plan</h2><button onClick={download} className="rounded bg-slate-700 px-4 py-2">Download plan &amp; specification</button></div>
      {!report.catalog_observed_by_decision && <p className="text-amber-200 text-sm">This catalog revision was registered after the scenario decision time. The plan uses backfilled metadata.</p>}
      <p className="text-sm text-slate-400">{report.note}</p>
      <pre className="bg-slate-950 p-4 rounded text-xs overflow-auto max-h-[600px]">{JSON.stringify(report.report.result, null, 2)}</pre>
    </section>}
  </div>
}

import { useEffect, useState, useCallback, useRef } from 'react'
import { FileText, RefreshCw, Terminal, Download, Trash2 } from 'lucide-react'

// System logs are often best served via WebSocket or a dedicated log endpoint
// For now, we'll implement a placeholder that could be wired to a real log tailer
const BASE = (import.meta as any).env?.VITE_API_URL ?? ''

interface LogEntry {
