  { id: 'use_crt', name: 'CRT', detail: 'Candle range theory setup' },
]
const DERIV_ASSETS = [
  { name: '1HZ75V', description: 'Volatility 75 (1s)', group: 'Synthetic indices' },
  { name: '1HZ100V', description: 'Volatility 100 (1s)', group: 'Synthetic indices' },
  { name: '1HZ50V', description: 'Volatility 50 (1s)', group: 'Synthetic indices' },
  { name: 'BOOM500', description: 'Boom 500 Index', group: 'Synthetic indices' },
  { name: 'CRASH500', description: 'Crash 500 Index', group: 'Synthetic indices' },
  { name: 'frxEURUSD', description: 'Euro / US Dollar', group: 'Forex' },
  { name: 'frxGBPUSD', description: 'British Pound / US Dollar', group: 'Forex' },
  { name: 'frxUSDJPY', description: 'US Dollar / Japanese Yen', group: 'Forex' },
]
const GROUPS = ['All groups', 'Stocks', 'Bonds', 'Forex', 'Indices', 'Commodities', 'Gold', 'Silver', 'Synthetic indices', 'Cryptocurrencies', 'Other']
type Broker = 'deriv' | 'mt5'
type Asset = { name: string; description: string; group: string; eligible?: boolean; reason?: string }
function classifyAsset(asset: { name: string; description?: string }): string {
  const name = asset.name.toLowerCase()
  const text = (asset.name + ' ' + (asset.description || '')).toLowerCase()
  if (/xau|gold/.test(text)) return 'Gold'
  if (/xag|silver/.test(text)) return 'Silver'
  if (/bond|treasury|gilt|bund|fixed income|t-note|10y|30y/.test(text)) return 'Bonds'
  if (/crypto|bitcoin|ethereum|(^|[^a-z])(btc|eth|ltc|xrp)([^a-z]|$)|btcusd|ethusd|ltcusd|xrpusd/.test(text)) return 'Cryptocurrencies'
  if (/commodity|commodities|x(pt|pd|ti|br)|wti|brent|crude|natural gas|oil|copper|platinum|palladium|wheat|coffee|cocoa/.test(text)) return 'Commodities'
  if (/forex|fx|frx/.test(text) || /^[a-z]{6}([._-].*)?$/.test(name)) return 'Forex'
  if (/synthetic|volatility|boom|crash|jump|step index|range break/.test(text)) return 'Synthetic indices'
  if (/index|indices|\.cash|nasdaq|s&p|dow jones|dax|ftse|nikkei/.test(text) || /^(us|nas|sp|uk|ger|de|fra|jp|hk)\d{2,4}/.test(name)) return 'Indices'
  if (/stock|share|equity|equities|inc\.|corp\.| plc/.test(text) || /^[a-z]{1,5}([._-].*)?$/.test(name)) return 'Stocks'
  return 'Other'
}
const DEFAULT_STRATEGIES = Object.fromEntries(STRATEGIES.map(item => [item.id, ['use_zscore', 'use_rsi', 'use_bb'].includes(item.id)]))
type Result = { symbol: string; total_pnl: number; win_rate: number; total_trades: number; max_drawdown: number }

export default function QuickTest() {
  const { canRunResearch } = usePermissions()
  const navigate = useNavigate()
  const [step, setStep] = useState(0)
  const [scanDepth, setScanDepth] = useState<'quick' | 'deep'>('quick')
  const [broker, setBroker] = useState<Broker>('deriv')
  const [brokerConnected, setBrokerConnected] = useState(false)
  const [brokerLoading, setBrokerLoading] = useState(false)
  const [brokerMessage, setBrokerMessage] = useState('')
  const [mt5Assets, setMt5Assets] = useState<Asset[]>([])
  const [assetGroup, setAssetGroup] = useState('All groups')
  const [assetSearch, setAssetSearch] = useState('')
  const [symbol, setSymbol] = useState('1HZ75V')
  const [strategies, setStrategies] = useState<Record<string, boolean>>(DEFAULT_STRATEGIES)
  const [timeframe, setTimeframe] = useState('M5')
  const [days, setDays] = useState(30)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [result, setResult] = useState<Result | null>(null)
  const [finished, setFinished] = useState(false)
  useEffect(() => {
    try {
      sessionStorage.setItem('research-selection-v1', JSON.stringify({ source: broker, symbols: [symbol], timeframe, days }))
    } catch { /* The guided test still works if browser storage is unavailable. */ }
  }, [broker, symbol, timeframe, days])
  const selectedStrategies = STRATEGIES.filter(item => strategies[item.id])
  const strategySummary = selectedStrategies.length === STRATEGIES.length
    ? 'All ' + STRATEGIES.length + ' strategies'
    : selectedStrategies.map(item => item.name).join(', ')
  const assets: Asset[] = broker === 'deriv'
    ? DERIV_ASSETS
    : mt5Assets.map(item => ({ ...item, group: classifyAsset(item) }))
  const searchTerm = assetSearch.trim().toLocaleLowerCase()
  const filteredAssets = assets.filter(item => {
    if (searchTerm) return (item.name + ' ' + item.description).toLocaleLowerCase().includes(searchTerm)
    return assetGroup === 'All groups' || item.group === assetGroup
  })
  function selectFirstMatchingAsset(listed: Asset[]) {
    const term = assetSearch.trim().toLocaleLowerCase()
    const match = listed.find(item => term
      ? (item.name + ' ' + item.description).toLocaleLowerCase().includes(term)
      : assetGroup === 'All groups' || item.group === assetGroup)
    if (match) setSymbol(match.name)
  }

  useEffect(() => {
    if (broker !== 'mt5') return
    let active = true
    setBrokerLoading(true); setBrokerMessage('')
    api.get('/api/mt5/status').then(async (status: any) => {
      if (!active) return
      if (!status.connected) {
        setBrokerConnected(false); setMt5Assets([])
        setBrokerMessage('Connect your MT5 terminal to load its broker instruments.')
        return
      }
      const data = await api.get('/api/mt5/symbols') as { symbols: Asset[] }
      if (active) {
        setBrokerConnected(true)
        const listed = data.symbols.map(row => ({ ...row, group: classifyAsset(row) }))
        setMt5Assets(listed)
        if (listed.length) selectFirstMatchingAsset(listed)
        setBrokerMessage(listed.length ? '' : 'No instruments were returned by the connected broker.')
      }
    }).catch(err => {
      if (active) { setBrokerConnected(false); setBrokerMessage(err instanceof Error ? err.message : 'Could not load the MT5 instrument list.') }
    }).finally(() => { if (active) setBrokerLoading(false) })
    return () => { active = false }
  }, [broker])

  async function connectMt5() {
    setBrokerLoading(true); setBrokerMessage('')
    try {
      await api.post('/api/mt5/connect', {})
      const data = await api.get('/api/mt5/symbols') as { symbols: Asset[] }
      const listed = data.symbols.map(row => ({ ...row, group: classifyAsset(row) }))
      setMt5Assets(listed); setBrokerConnected(true)
      if (listed.length) selectFirstMatchingAsset(listed)
      setBrokerMessage(listed.length ? '' : 'Connected, but no instruments were returned.')
    } catch (err) {
      setBrokerConnected(false)
      setBrokerMessage(err instanceof Error ? err.message : 'Could not connect to MT5. Check that the terminal is installed and logged in.')
    } finally { setBrokerLoading(false) }
  }

  function changeBroker(value: Broker) {
    setBroker(value); setAssetGroup('All groups'); setAssetSearch('')
    const first = value === 'deriv' ? DERIV_ASSETS[0]?.name : mt5Assets[0]?.name
    if (first) setSymbol(first)
  }

  async function runTest() {
    if (!canRunResearch || loading) return
    setLoading(true); setError(''); setResult(null); setFinished(false)
    try {
      const data = await api.post('/api/backtest/run', {
        data_source: broker, symbols: [symbol], timeframe, days, initial_balance: 10000,
        min_confluence: 3, csv_data: null, ...strategies, strategy_versions: {}, news_only: false,
      }) as Result[]
      if (!data || !data.length) throw new Error('The test finished without a result. Try another asset or interval.')
      setResult(data[0]); setFinished(true)
    } catch (err) { setError(err instanceof Error ? err.message : 'The test could not be completed.') }
    finally { setLoading(false) }
  }
  function startOver() { setStep(0); setResult(null); setError(''); setFinished(false) }

  return <div className="min-h-full px-4 py-10 sm:px-8"><div className="mx-auto max-w-2xl">
    <div className="mb-8"><p className="text-sm font-medium text-cyan-300">STRATEGY TESTER</p><h1 className="mt-2 text-3xl font-bold text-white">Run a test</h1><p className="mt-2 text-slate-400">Choose what to test. We’ll run it on past market data and show you what happened.</p></div>
    {!finished && <div className="mb-5 flex items-center gap-2" aria-label={'Step ' + (step + 1) + ' of 3'}>{[0,1,2].map(index => <div key={index} className={'h-1.5 flex-1 rounded-full ' + (index <= step ? 'bg-cyan-400' : 'bg-slate-700')} />)}<span className="ml-2 text-xs text-slate-400">Step {step + 1} of 3</span></div>}
    <section className="rounded-2xl border border-slate-700 bg-slate-800 p-5 shadow-xl sm:p-7">
      {step === 0 && <div className="mb-6"><p className="mb-3 text-sm font-medium text-slate-300">Choose scan depth</p><div className="grid gap-3 sm:grid-cols-2"><button type="button" aria-pressed={scanDepth === 'quick'} onClick={() => setScanDepth('quick')} className={'rounded-xl border p-4 text-left ' + (scanDepth === 'quick' ? 'border-cyan-400 bg-cyan-400/10' : 'border-slate-600 bg-slate-900 hover:border-slate-400')}><span className="block font-semibold text-white">Quick scan</span><span className="mt-1 block text-sm text-slate-400">Fast historical strategy test with a simple results summary.</span></button><button type="button" aria-pressed={scanDepth === 'deep'} onClick={() => setScanDepth('deep')} className={'rounded-xl border p-4 text-left ' + (scanDepth === 'deep' ? 'border-cyan-400 bg-cyan-400/10' : 'border-slate-600 bg-slate-900 hover:border-slate-400')}><span className="block font-semibold text-white">Deep scan</span><span className="mt-1 block text-sm text-slate-400">Checks data quality, trading costs, market hours, and out-of-sample results.</span></button></div></div>}
      {loading ? <div className="py-12 text-center" role="status"><LoaderCircle className="mx-auto h-10 w-10 animate-spin text-cyan-300" /><h2 className="mt-5 text-xl font-semibold text-white">Running your test…</h2><p className="mt-2 text-slate-400">Getting market history, checking the strategy, and preparing your results.</p><p className="mt-5 text-sm text-slate-500">You can wait here. This does not place a trade.</p></div>
      : finished && result ? <div><div className="flex items-center gap-3"><div className="rounded-full bg-emerald-500/15 p-2 text-emerald-300"><Check /></div><div><p className="text-sm text-emerald-300">Test complete</p><h2 className="text-2xl font-bold text-white">{result.symbol} · {timeframe}</h2></div></div><p className="mt-3 text-slate-400">{broker === 'mt5' ? 'MT5' : 'Deriv'} · {strategySummary} · past {days} days</p><div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-4"><Metric label="Profit / loss" value={(result.total_pnl >= 0 ? '+' : '') + Number(result.total_pnl || 0).toFixed(2)} positive={result.total_pnl >= 0} /><Metric label="Winning trades" value={(Number(result.win_rate || 0) * 100).toFixed(1) + '%'} /><Metric label="Number of trades" value={String(result.total_trades ?? 0)} /><Metric label="Largest drop" value={(Number(result.max_drawdown || 0) * 100).toFixed(1) + '%'} /></div><p className="mt-5 rounded-lg bg-slate-900 p-3 text-sm text-slate-400">This is a simulation using historical data. Past results don’t guarantee future results. No real trade was placed.</p><button onClick={startOver} className="mt-6 inline-flex items-center gap-2 rounded-lg bg-cyan-400 px-5 py-3 font-semibold text-slate-950 hover:bg-cyan-300"><RotateCcw size={18} /> Run another test</button></div>
      : <>
        {step === 0 && <><p className="text-sm text-cyan-300">1 · Choose a broker and market</p><h2 className="mt-2 text-2xl font-semibold text-white">Where should we look?</h2><p className="mt-2 text-slate-400">Choose the broker first. We’ll show only instruments available from that source.</p><label className="mt-6 block text-sm text-slate-300">Broker or data source<select value={broker} onChange={event => changeBroker(event.target.value as Broker)} className="mt-2 w-full rounded-lg border border-slate-600 bg-slate-900 p-3 text-white"><option value="deriv">Deriv · public history</option><option value="mt5">MetaTrader 5 · connected broker</option></select></label><label className="mt-4 block text-sm text-slate-300">Search for a pair or instrument<input aria-label="Search for a pair or instrument" placeholder="Try GER40, EURUSD, gold..." value={assetSearch} onChange={event => { const query = event.target.value; setAssetSearch(query); if (query.trim()) setAssetGroup('All groups'); const term = query.trim().toLocaleLowerCase(); const matches = assets.filter(item => !term || (item.name + ' ' + item.description).toLocaleLowerCase().includes(term)); if (matches.length) setSymbol(matches[0].name) }} className="mt-2 w-full rounded-lg border border-slate-600 bg-slate-900 p-3 text-white placeholder:text-slate-500" /></label>{broker === 'mt5' && <div className="mt-4 rounded-xl border border-slate-700 bg-slate-900 p-4"><p className="text-sm text-slate-300">{brokerConnected ? 'Connected. Instruments are loaded from your broker.' : brokerMessage || 'Connect MT5 to load broker instruments.'}</p>{!brokerConnected && <button type="button" disabled={brokerLoading} onClick={connectMt5} className="mt-3 rounded-lg bg-slate-700 px-4 py-2 text-sm font-medium text-white disabled:opacity-50">{brokerLoading ? 'Connecting…' : 'Connect MT5 and load instruments'}</button>}</div>}<div className="mt-4 grid grid-cols-2 gap-3"><label className="text-sm text-slate-300">Asset group<select value={assetGroup} onChange={event => { setAssetGroup(event.target.value); setAssetSearch(''); const next = assets.filter(item => event.target.value === 'All groups' || item.group === event.target.value); if (next.length) setSymbol(next[0].name) }} className="mt-2 w-full rounded-lg border border-slate-600 bg-slate-900 p-3 text-white">{GROUPS.map(group => <option key={group}>{group}</option>)}</select></label><label className="text-sm text-slate-300">Market<select value={symbol} onChange={event => setSymbol(event.target.value)} disabled={!filteredAssets.length || (broker === 'mt5' && !brokerConnected)} className="mt-2 w-full rounded-lg border border-slate-600 bg-slate-900 p-3 text-white">{filteredAssets.map(asset => <option key={asset.name} value={asset.name}>{asset.name}{asset.description ? ' · ' + asset.description : ''}</option>)}</select></label></div>{broker === 'mt5' && brokerConnected && mt5Assets.find(item => item.name === symbol)?.eligible === false && <p className="mt-2 text-xs text-amber-300">This broker instrument is not eligible for demo execution, but its historical data can still be tested.</p>}{brokerMessage && broker === 'mt5' && brokerConnected && <p className="mt-2 text-xs text-amber-300">{brokerMessage}</p>}{!filteredAssets.length && <p className="mt-2 text-sm text-slate-400">{broker === 'mt5' ? (brokerConnected ? 'No instruments in this group are available from the connected broker.' : 'Connect MT5 to see instruments in this group.') : 'No instruments are available in this group for Deriv.'}</p>}<div className="mt-4 grid grid-cols-2 gap-3"><label className="text-sm text-slate-300">Chart interval<select value={timeframe} onChange={event => setTimeframe(event.target.value)} className="mt-2 w-full rounded-lg border border-slate-600 bg-slate-900 p-3 text-white">{['M1','M5','M15','M30','H1','H4'].map(tf => <option key={tf}>{tf}</option>)}</select></label><label className="text-sm text-slate-300">History to check<select value={days} onChange={event => setDays(Number(event.target.value))} className="mt-2 w-full rounded-lg border border-slate-600 bg-slate-900 p-3 text-white"><option value={7}>Past 7 days</option><option value={30}>Past 30 days</option><option value={90}>Past 90 days</option></select></label></div></>}
        {step === 1 && <><p className="text-sm text-cyan-300">2 · Active strategies</p><h2 className="mt-2 text-2xl font-semibold text-white">Choose what to include</h2><p className="mt-2 text-slate-400">Select any combination, or use Select all to include every strategy.</p><div className="mt-5 flex flex-wrap gap-3"><button type="button" onClick={() => setStrategies(Object.fromEntries(STRATEGIES.map(item => [item.id, true])))} className="rounded-lg bg-slate-700 px-4 py-2 text-sm font-medium text-white hover:bg-slate-600">Select all</button><button type="button" onClick={() => setStrategies(Object.fromEntries(STRATEGIES.map(item => [item.id, false])))} className="rounded-lg bg-slate-700 px-4 py-2 text-sm font-medium text-white hover:bg-slate-600">Clear all</button><span className="self-center text-sm text-slate-400">{selectedStrategies.length} of {STRATEGIES.length} selected</span></div><div className="mt-4 max-h-[52vh] space-y-2 overflow-y-auto pr-1">{STRATEGIES.map(item => <button key={item.id} onClick={() => setStrategies(previous => ({ ...previous, [item.id]: !previous[item.id] }))} aria-pressed={strategies[item.id]} className={'flex w-full items-center justify-between rounded-xl border p-3 text-left transition ' + (strategies[item.id] ? 'border-cyan-500/50 bg-cyan-500/10 text-cyan-300' : 'border-slate-600 bg-slate-900 text-slate-400 hover:border-slate-500')}><span><span className="block font-semibold">{item.name}</span><span className="mt-1 block text-xs opacity-70">{item.detail}</span></span><span aria-hidden="true" className="ml-3 text-lg">{strategies[item.id] ? '✓' : '×'}</span></button>)}</div></>}
        {step === 2 && <><p className="text-sm text-cyan-300">3 · Ready to run</p><h2 className="mt-2 text-2xl font-semibold text-white">Here’s your test</h2><p className="mt-2 text-slate-400">Check the choices, then press the button. You can change them at any time.</p><dl className="mt-6 divide-y divide-slate-700 rounded-xl bg-slate-900 px-4"><Summary label="Broker" value={broker === 'mt5' ? 'MetaTrader 5' : 'Deriv'} /><Summary label="Market" value={symbol} /><Summary label="Interval" value={timeframe} /><Summary label="History" value={'Past ' + days + ' days'} /><Summary label="Strategies" value={strategySummary} /></dl>{!canRunResearch && <p className="mt-4 text-sm text-amber-300">Your account can view results but cannot run a new test.</p>}</>}
        {error && <p role="alert" className="mt-5 rounded-lg bg-red-950/40 p-3 text-sm text-red-200">{error}</p>}
        <div className="mt-7 flex justify-between gap-3"><button onClick={() => step === 0 ? startOver() : setStep(step - 1)} className="inline-flex items-center gap-2 rounded-lg px-4 py-3 text-slate-300 hover:bg-slate-700"><ArrowLeft size={18} />{step === 0 ? 'Start over' : 'Back'}</button>{step < 2 ? <button onClick={() => step === 0 && scanDepth === 'deep' ? navigate('/analyze', { state: { source: broker, symbol, symbols: [symbol], timeframe, days, scanDepth: 'deep' } }) : setStep(step + 1)} disabled={(step === 0 && (!filteredAssets.length || brokerLoading || (broker === 'mt5' && !brokerConnected))) || (step === 1 && selectedStrategies.length === 0)} className="inline-flex items-center gap-2 rounded-lg bg-cyan-400 px-5 py-3 font-semibold text-slate-950 hover:bg-cyan-300 disabled:cursor-not-allowed disabled:opacity-50">{step === 0 && scanDepth === 'deep' ? 'Continue to deep scan' : 'Continue'}<ArrowRight size={18} /></button> : <button onClick={runTest} disabled={!canRunResearch} className="inline-flex items-center gap-2 rounded-lg bg-cyan-400 px-5 py-3 font-semibold text-slate-950 hover:bg-cyan-300 disabled:cursor-not-allowed disabled:opacity-50"><Play size={18} />Run test</button>}</div>
      </>}
    </section>
    {!finished && <p className="mt-4 text-center text-xs text-slate-500">Historical simulation only · No real trades</p>}
  </div></div>
}

function Metric({ label, value, positive }: { label: string; value: string; positive?: boolean }) { return <div className="rounded-xl bg-slate-900 p-4"><p className="text-xs text-slate-400">{label}</p><p className={'mt-2 text-xl font-bold ' + (positive === undefined ? 'text-white' : positive ? 'text-emerald-300' : 'text-rose-300')}>{value}</p></div> }
function Summary({ label, value }: { label: string; value: string }) { return <div className="flex justify-between gap-4 py-4 text-sm"><dt className="text-slate-400">{label}</dt><dd className="font-medium text-white">{value}</dd></div> }

import { useEffect, useState, useCallback } from 'react'
import { 
  Shield, AlertTriangle, Activity, 
  ArrowUpRight, ArrowDownRight, Info,
  RefreshCw, RotateCcw
} from 'lucide-react'
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, 
  Tooltip, ResponsiveContainer, YAxisProps
} from 'recharts'
import { fetchRisk, resetCircuitBreaker, type RiskDashboard } from '../api/client'
import { format } from 'date-fns'

export default function Risk() {
  const [data, setData] = useState<RiskDashboard | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [resetting, setResetting] = useState(false)

  const loadRisk = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetchRisk()
      setData(res)
      setError(null)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadRisk()
  }, [loadRisk])

  const handleResetCB = async () => {
    if (!confirm('Are you sure you want to manually reset the circuit breaker?')) return
    setResetting(true)
    try {
      await resetCircuitBreaker()
      await loadRisk()
    } catch (err: any) {
      alert('Reset failed: ' + err.message)
    } finally {
      setResetting(false)
    }
  }

  if (loading && !data) {
    return <div className="p-12 text-center text-slate-500">Loading risk metrics...</div>
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">Risk Dashboard</h1>
          <p className="text-slate-400 text-sm">Monitor exposure and circuit breaker status</p>
        </div>
        <button 
            onClick={() => loadRisk()}
            className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
        >
            <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard 
            label="Current Balance" 
            value={data?.current_balance ? `$${data.current_balance.toFixed(2)}` : '—'} 
        />
        <StatCard 
            label="Daily PnL" 
            value={data?.daily_pnl ? `$${data.daily_pnl.toFixed(2)}` : '—'} 
            sub={data?.daily_pnl ? `${data.daily_pnl >= 0 ? '+' : ''}${data.daily_pnl.toFixed(2)}` : undefined}
            accent={data?.daily_pnl !== null && data?.daily_pnl !== undefined && data.daily_pnl < 0 ? 'text-red-400' : 'text-emerald-400'}
        />
        <StatCard 
            label="Daily Drawdown" 
            value={`${data?.daily_drawdown_pct.toFixed(2)}%`} 
            accent={data?.daily_drawdown_pct && data.daily_drawdown_pct > 2 ? 'text-red-400' : 'text-slate-200'}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-slate-800 border border-slate-700 rounded-xl p-6">
          <h3 className="text-white font-bold mb-6 flex items-center gap-2">
            <Activity className="w-4 h-4 text-cyan-400" />
            Equity Curve (Last 48 Points)
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={data?.equity_curve || []}>
                <defs>
                  <linearGradient id="colorBalance" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#06b6d4" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#06b6d4" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                <XAxis 
                  dataKey="ts" 
                  stroke="#64748b" 
                  fontSize={10}
                  tickFormatter={(t) => format(new Date(t), 'HH:mm')}
                />
                <YAxis 
                  stroke="#64748b" 
                  fontSize={10} 
                  domain={['auto', 'auto']}
                  tickFormatter={(v) => `$${v}`}
                />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }}
                  labelStyle={{ color: '#94a3b8', fontSize: '10px', marginBottom: '4px' }}
                  itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                  labelFormatter={(t) => format(new Date(t), 'MMM dd, HH:mm')}
                />
                <Area 
                  type="monotone" 
                  dataKey="balance" 
                  stroke="#06b6d4" 
                  fillOpacity={1} 
                  fill="url(#colorBalance)" 
                  strokeWidth={2}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-slate-800 border border-slate-700 rounded-xl p-6 flex flex-col">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-white font-bold flex items-center gap-2">
              <Shield className="w-4 h-4 text-emerald-400" />
              Circuit Breaker
            </h3>
            <button 
                onClick={handleResetCB}
                disabled={resetting}
                className="text-[10px] uppercase font-bold text-cyan-400 hover:text-cyan-300 transition-colors flex items-center gap-1"
            >
                <RotateCcw className={`w-3 h-3 ${resetting ? 'animate-spin' : ''}`} />
                Reset
            </button>
          </div>
          
          <div className="flex-1 space-y-4">
            {data?.circuit_breaker_history.length === 0 ? (
                <div className="text-center py-12 text-slate-500 text-sm italic">
                    No circuit breaker events logged
                </div>
            ) : (
                data?.circuit_breaker_history.map((event, i) => (
                    <div key={i} className="flex gap-3">
                        <div className={`mt-1 w-2 h-2 rounded-full shrink-0 ${
                            event.severity === 'critical' ? 'bg-red-500' : 
                            event.severity === 'warning' ? 'bg-yellow-500' : 'bg-emerald-500'
                        }`} />
                        <div>
                            <div className="text-xs font-bold text-white uppercase tracking-tight">{event.event_type}</div>
                            <div className="text-[11px] text-slate-400 leading-relaxed mb-1">{event.message}</div>
                            <div className="text-[9px] text-slate-500">{format(new Date(event.ts), 'MMM dd, HH:mm:ss')}</div>
                        </div>
                    </div>
                ))
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

function StatCard({ label, value, sub, accent }: { label: string, value: string, sub?: string, accent?: string }) {
    return (
        <div className="bg-slate-800 border border-slate-700 rounded-xl p-6">
            <div className="text-xs text-slate-500 uppercase font-bold tracking-wider mb-2">{label}</div>
            <div className={`text-3xl font-bold ${accent || 'text-white'}`}>{value}</div>
            {sub && <div className="text-xs text-slate-500 mt-1">{sub}</div>}
        </div>
    )
}

import { useEffect, useRef, useState } from 'react'
import { api, downloadFile } from '../api/client'
import { usePermissions } from '../auth/identity'

const button = 'px-3 py-2 rounded bg-cyan-800 disabled:opacity-40'
const SIGNAL_INDICATORS = [
  ['use_zscore', 'Z-Score'], ['use_rsi', 'RSI'], ['use_bb', 'Bollinger Bands'],
  ['use_vwap', 'VWAP'], ['use_stoch', 'Stochastic'], ['use_lsl', 'Liquidity Sweep'],
  ['use_smc', 'SMC Structure'], ['use_volume', 'Volume Filter'], ['use_hurst', 'Hurst Regime'],
  ['use_crt', 'CRT'],
] as const
const defaultStrategyOptions = () => ({
  use_zscore: true, use_rsi: true, use_bb: true, use_vwap: true, use_stoch: true,
  use_lsl: true, use_smc: true, use_volume: true, use_hurst: false, use_crt: false,
})
export default function Scanner() {
  const { canRunResearch } = usePermissions()
  const [state, setState] = useState<any>(null)
  const [ledger, setLedger] = useState<any>({ observations: [], trades: [] })
  const [analytics, setAnalytics] = useState<any>(null)
  const [symbols, setSymbols] = useState<any[]>([])
  const [selected, setSelected] = useState<string[]>([])
  const [query, setQuery] = useState('')
  const [timeframe, setTimeframe] = useState('M5')
  const [threshold, setThreshold] = useState(6)
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [restored, setRestored] = useState<any>({})
  const [historyKind, setHistoryKind] = useState('observations')
  const [historyPage, setHistoryPage] = useState<any>(null)
  const [historyBusy, setHistoryBusy] = useState(false)
  const [exportBusy, setExportBusy] = useState(false)
  const [group, setGroup] = useState('symbol')
  const [strategyOptions, setStrategyOptions] = useState<Record<string, boolean>>(defaultStrategyOptions)
  const [notificationsEnabled, setNotificationsEnabled] = useState(false)
  const notifiedSignals = useRef<Set<string>>(new Set())
  const initialLoad = useRef(true)
  const local = ['localhost', '127.0.0.1', '[::1]'].includes(window.location.hostname)
  const active = state?.run?.status === 'running'
  const candidateMode = restored.strategy_mode === 'research_candidate'
  const singlePairRun = state?.run?.config?.assets?.length === 1 ? state.run : null
  const singlePair = singlePairRun?.config.assets[0].symbol
  const singleScope = singlePairRun?.config.candidate_snapshot
    ? `${singlePairRun.config.candidate_snapshot.server}:${singlePairRun.config.candidate_snapshot.account}` : null
  const paperSignal = singlePairRun && (state?.latest || []).find((row: any) =>
    row.run_id === singlePairRun.id && row.symbol === singlePair &&
    row.timeframe === singlePairRun.config.timeframe && (!singleScope || row.scope === singleScope))
  const refresh = async () => {
    const [s, l, a] = await Promise.all([api.get('/api/scanner'), api.get('/api/scanner/ledger'), api.get('/api/scanner/analytics')])
    const scannerStatus = s as any
    const latest = scannerStatus.latest || []
    if (initialLoad.current) {
      latest.forEach((row: any) => { if (row.id) notifiedSignals.current.add(row.id) })
      initialLoad.current = false
    } else if (notificationsEnabled && 'Notification' in window && Notification.permission === 'granted') {
      latest.forEach((row: any) => {
        if (!row.id || notifiedSignals.current.has(row.id)) return
        notifiedSignals.current.add(row.id)
        if (row.eligible && ['buy', 'sell'].includes(row.direction)) {
          const notice = new Notification(`${row.direction.toUpperCase()} signal · ${row.symbol}`, {
            body: `${row.timeframe} · score ${row.score ?? 'N/A'}/100 · ${row.strategy_reason || 'Paper setup eligible'}`,
          })
          notice.onclick = () => window.focus()
        }
      })
    }
    setState(scannerStatus); setLedger(l); setAnalytics(a)
  }
  useEffect(() => {
    if (!local) return
    let mounted = true
    const poll = () => { if (mounted) refresh().catch(e => setError(String(e))) }
    poll(); const timer = setInterval(poll, 5000)
    return () => { mounted = false; clearInterval(timer) }
  }, [notificationsEnabled])
  async function catalog() {
    setBusy(true); setError('')
    try { const data: any = await api.get('/api/mt5/symbols'); setSymbols(data.symbols || []) }
    catch (e) { setError(String(e)) } finally { setBusy(false) }
  }
  async function loadHistory(kind: string, older = false) {
    setHistoryBusy(true); setError('')
    const cursor = older ? `&through=${historyPage.through}&before=${historyPage.next_before}` : ''
    try { setHistoryPage(await api.get(`/api/scanner/records?kind=${kind}&limit=50${cursor}`)) }
    catch (e) { setError(String(e)) } finally { setHistoryBusy(false) }
  }
  async function exportEvidence() {
    setExportBusy(true); setError('')
    try { await downloadFile('/api/scanner/export', 'scanner-evidence.json') }
    catch (e) { setError(String(e)) } finally { setExportBusy(false) }
  }
  function restoreSettings() {
    const config = state?.run?.config
    if (!config) return
    setRestored(config); setSelected(config.assets.map((a: any) => a.symbol))
    setTimeframe(config.timeframe); setThreshold(config.threshold)
    if (config.strategy) setStrategyOptions(Object.fromEntries(SIGNAL_INDICATORS.map(([key]) => [key, Boolean(config.strategy[key])])))
  }
  async function loadCandidate() {
    setBusy(true); setError('')
    try {
      const status: any = await api.get('/api/mt5/status')
      const candidate = status.research_candidate
      if (!status.research_validated || !candidate?.strategy?.symbol) {
        throw new Error('Load a passing single-pair candidate from Analyze selected assets into MT5 Demo & Journal first.')
      }
      const strategy = candidate.strategy
      setSelected([strategy.symbol]); setTimeframe(strategy.timeframe); setThreshold(strategy.min_confluence)
      setRestored((previous: any) => ({ ...previous, assets: [{ symbol: strategy.symbol }],
        strategy_mode: 'research_candidate', strategy, research_run_id: candidate.run_id,
        candidate_snapshot: candidate.snapshot }))
    } catch (e) { setError(String(e)) } finally { setBusy(false) }
  }
  async function control(action: string) {
    setBusy(true); setError('')
    try {
      const request = action === 'start' ? candidateMode ? {
        ...restored, assets: selected.map(symbol => restored.assets?.find((a: any) => a.symbol === symbol) || { symbol }), timeframe, threshold,
      } : {
        ...restored,
        assets: selected.map(symbol => restored.assets?.find((a: any) => a.symbol === symbol) || { symbol }),
        timeframe, threshold, strategy_mode: 'manual',
        strategy: { symbol: selected[0], timeframe, min_confluence: threshold, ...strategyOptions },
      } : {}
      await api.post(`/api/scanner/${action}`, request)
      await refresh()
    } catch (e) { setError(String(e)) } finally { setBusy(false) }
  }
  async function enableNotifications() {
    if (!('Notification' in window)) {
      setError('This browser does not support desktop notifications.')
      return
    }
    try {
      const permission = await Notification.requestPermission()
      if (permission === 'granted') setNotificationsEnabled(true)
      else setError('Browser notification permission was not granted; scanner signals remain visible on this page.')
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
    }
  }
  const hasDirectionalIndicator = ['use_zscore', 'use_rsi', 'use_bb', 'use_vwap', 'use_stoch', 'use_lsl', 'use_smc']
    .some(key => strategyOptions[key])
  if (!local) return <div className="p-6">Forward scanning requires the local app and your connected MT5 demo terminal.</div>
  return <div className="p-4 md:p-6 space-y-5 max-w-7xl mx-auto">
    <header><h1 className="text-2xl font-bold">Forward scanner</h1><p className="text-slate-300 mt-2">Continuously observe up to eight MT5 pairs and record hypothetical signals. Scanning never starts or approves broker trades.</p></header>
    {error && <p role="alert" className="p-3 bg-red-950 rounded break-words">{error}</p>}
    <section className="bg-slate-800 rounded-xl p-4 space-y-4">
      <div className="flex flex-wrap gap-3 items-center"><a className="text-cyan-300 underline" href="/mt5">Connect MT5 demo</a><button className={button} disabled={busy} onClick={() => void catalog()}>Load broker symbols</button><button className={button} disabled={!canRunResearch || busy || active || !state?.run?.config} onClick={restoreSettings}>Load saved scanner settings</button><button className={button} disabled={!canRunResearch || busy || active} onClick={() => void loadCandidate()}>Use loaded research candidate</button><span>{state?.run?.status || 'Not started'}</span></div>
      <label className="block">Find instruments<input className="block mt-1 bg-slate-900 rounded p-2 w-full" value={query} onChange={e => setQuery(e.target.value)} /></label>
      <div className="max-h-52 overflow-auto flex flex-wrap gap-2" aria-label="Scanner assets">
        {symbols.filter(s => `${s.name} ${s.description}`.toLowerCase().includes(query.toLowerCase())).map(s => <button key={s.name} aria-pressed={selected.includes(s.name)} disabled={!canRunResearch || active || busy || candidateMode || !s.eligible || (!selected.includes(s.name) && selected.length >= 8)} className={`px-3 py-2 rounded border disabled:opacity-40 ${selected.includes(s.name) ? 'bg-cyan-700 border-cyan-400' : 'border-slate-600'}`} onClick={() => setSelected(p => p.includes(s.name) ? p.filter(n => n !== s.name) : [...p, s.name])}>{s.name}</button>)}
      </div>
      <p className="text-sm break-words">Selected: {selected.join(', ') || 'Load the connected catalog and select pairs'}</p>
      {candidateMode && <div className="text-sm text-cyan-200">Research candidate {restored.research_run_id || 'loaded'} · one pair · strategy and threshold locked to the validated report. <button className="underline" disabled={busy || active} onClick={() => setRestored((previous: any) => ({ ...previous, strategy_mode: 'manual', strategy: undefined, research_run_id: undefined, candidate_snapshot: undefined }))}>Use manual scanner settings</button></div>}
      <div className="flex flex-wrap gap-4 items-end">
        <label>Timeframe<select className="block bg-slate-900 p-2 rounded" value={timeframe} disabled={active || busy || candidateMode} onChange={e => setTimeframe(e.target.value)}>{['M1','M5','M15','M30','H1','H4'].map(t => <option key={t}>{t}</option>)}</select></label>
        <label>Paper spread model<select className="block bg-slate-900 p-2 rounded" value={restored.spread_model || 'fixed_quote'} disabled={!canRunResearch || active || busy} onChange={e => setRestored((p: any) => ({ ...p, spread_model: e.target.value }))}><option value="fixed_quote">Fixed observed quote</option><option value="candle_proxy_v1">Historical candle proxy</option></select></label>
        <label>Minimum weighted score<input className="block bg-slate-900 p-2 rounded w-24" type="number" min="1" max="20" value={threshold} disabled={active || busy || candidateMode} onChange={e => setThreshold(Number(e.target.value))} /></label>
        <label>Poll interval (seconds)<input className="block bg-slate-900 p-2 rounded w-28" type="number" min="15" max="300" step="5" value={restored.poll_seconds ?? 30} disabled={!canRunResearch || active || busy} onChange={e => setRestored((p: any) => ({ ...p, poll_seconds: Number(e.target.value) }))} /></label>
        <label>Maximum spread / ATR<input className="block bg-slate-900 p-2 rounded w-28" type="number" min="0.01" max="1" step="0.01" value={restored.max_spread_atr ?? 0.2} disabled={!canRunResearch || active || busy} onChange={e => setRestored((p: any) => ({ ...p, max_spread_atr: Number(e.target.value) }))} /></label>
        <label>Slippage / ATR<input className="block bg-slate-900 p-2 rounded w-28" type="number" min="0" max="0.5" step="0.01" value={restored.slippage_atr ?? 0.02} disabled={!canRunResearch || active || busy} onChange={e => setRestored((p: any) => ({ ...p, slippage_atr: Number(e.target.value) }))} /></label>
        <label>Max holding bars<input className="block bg-slate-900 p-2 rounded w-24" type="number" min="1" max="100" value={restored.max_hold_bars ?? 12} disabled={!canRunResearch || active || busy} onChange={e => setRestored((p: any) => ({ ...p, max_hold_bars: Number(e.target.value) }))} /></label>
        <button className={button} disabled={!canRunResearch || busy || active || !selected.length || !Number.isInteger(threshold) || threshold < 1 || threshold > 20 || (!candidateMode && !hasDirectionalIndicator)} onClick={() => void control('start')}>Start paper scanner</button>
        <button className={button} disabled={!canRunResearch || busy || !active} onClick={() => void control('stop')}>Stop scanner</button>
        <button className={button} disabled={!canRunResearch || notificationsEnabled || !('Notification' in window)} onClick={() => void enableNotifications()}>{notificationsEnabled ? 'Browser alerts enabled' : 'Enable browser alerts'}</button>
      </div>
      <fieldset disabled={!canRunResearch || active || busy || candidateMode} className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
        <legend className="text-sm font-medium mb-2">Indicators required by the signal strategy</legend>
        {SIGNAL_INDICATORS.map(([key, label]) => <label key={key} className="rounded border border-slate-700 px-3 py-2 text-sm"><input type="checkbox" checked={Boolean(strategyOptions[key])} onChange={e => setStrategyOptions(old => ({ ...old, [key]: e.target.checked }))} /> <span className="ml-2">{label}</span></label>)}
      </fieldset>
      {!candidateMode && !hasDirectionalIndicator && <p className="text-sm text-amber-200">Choose at least one directional indicator. Volume and Hurst filters alone do not produce a BUY or SELL direction.</p>}
      <p className="text-sm text-slate-400">{candidateMode ? 'Signal indicators and threshold follow the loaded research candidate. The scanner still applies its own conservative paper regime gate and cost assumptions.' : 'Manual mode uses the selected indicators and minimum score above.'} Score /100 is weighted points /20, capped at 100; it is not a probability. RANGE requires Hurst below 0.45 and drift below 3 ATR. Trend, wide spread, volatility spikes, uncertain regimes and stale/gapped data block new paper entries.</p>
      <p className="text-sm text-amber-200">News and macro coverage: unknown. Liquidity is a spread proxy, not order-book depth. Session groups use six-hour UTC buckets. These exploratory observations do not qualify a strategy for execution.</p>
      <p className="text-sm text-slate-400">Historical candle mode uses each recorded bar spread as an ask-price proxy, not an executable quote. Missing or unconfirmed zero spreads leave outcomes unresolved. Commission and financing remain unmodeled.</p>
      <p className="text-xs text-slate-400">Polling: {restored.poll_seconds ?? 30}s | Max spread/ATR: {restored.max_spread_atr ?? 0.2} | Slippage/ATR: {restored.slippage_atr ?? 0.02} | Max holding bars: {restored.max_hold_bars ?? 12}. Loading saved settings restores these limits too.</p>
      <p className="text-xs text-slate-400">{notificationsEnabled ? 'Desktop alerts are enabled for new eligible BUY/SELL paper signals while this page is open.' : 'Enable browser alerts to be notified of new eligible BUY/SELL paper signals while this page is open.'} No signal is guaranteed, and alerts never place orders.</p>
      {state?.run && <p className="text-xs text-slate-400 break-words">Active/saved selection: {state.run.config.assets.map((a: any) => a.symbol).join(', ')} · {state.run.config.timeframe} · started {new Date(state.run.created * 1000).toLocaleString()}{state.run.error && ` · ${state.run.error}`}</p>}
    </section>
    {singlePairRun && <section className="bg-slate-800 rounded-xl p-4 space-y-2" aria-label="Latest single-pair paper signal">
      <h2 className="font-semibold">Latest paper signal · {singlePair}</h2>
      <p className="text-xs text-slate-300 break-words">{singleScope || 'Manual scanner account'} · {singlePairRun.config.timeframe} · {singlePairRun.config.strategy_mode === 'research_candidate' ? `Research ${singlePairRun.config.research_run_id}` : 'Manual settings'} · Scanner {singlePairRun.status}</p>
      {paperSignal ? <>
        <p className="text-sm">{paperSignal.strategy_setup === true && ['buy', 'sell'].includes(paperSignal.direction) ? `Strategy setup ${paperSignal.direction.toUpperCase()}` : paperSignal.strategy_setup === false ? 'No strategy setup' : 'Strategy setup not recorded for this observation'} · {paperSignal.strategy_reason || paperSignal.reasons?.[0] || 'No strategy reason recorded'}</p>
        <p className={paperSignal.eligible ? 'text-emerald-300' : 'text-amber-200'}>{paperSignal.eligible && ['buy', 'sell'].includes(paperSignal.direction) ? `Paper entry eligible ${paperSignal.direction.toUpperCase()}` : 'Paper entry blocked'} · score {paperSignal.score ?? 'N/A'}/100 · regime {paperSignal.regime || 'unknown'}</p>
        <p className="text-sm">Observed {new Date(paperSignal.observed * 1000).toLocaleString()} · closed candle {paperSignal.bar ? new Date(paperSignal.bar * 1000).toLocaleString() : 'unavailable'}</p>
        <p className="text-sm text-slate-300 break-words">{paperSignal.reasons?.join('; ') || 'No reason recorded'}</p>
      </> : <p className="text-sm text-slate-400">No observation for this exact pair and scanner run yet.</p>}
      <p className="text-xs text-slate-400">Paper observation only. It does not place an MT5 order; demo execution is a separate explicit step.</p>
    </section>}
    <section className="bg-slate-800 rounded-xl p-4"><h2 className="font-semibold mb-3">Latest observations</h2><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-sm text-left"><thead><tr>{['Pair','Observed','Regime','Deviation','Score /100','Direction','Action / reasons'].map(h => <th className="p-2" key={h}>{h}</th>)}</tr></thead><tbody>{(state?.latest || []).map((r: any) => <tr key={r.symbol} className="border-t border-slate-700"><td className="p-2">{r.symbol}<details><summary className="text-cyan-300 cursor-pointer">Instrument identity</summary><p>{r.scope || 'Legacy account unknown'}</p><pre className="whitespace-pre-wrap break-all max-w-xs text-xs">{JSON.stringify(r.instrument || { provider: r.provider, symbol: r.symbol, scope: r.scope }, null, 2)}</pre></details></td><td>{new Date(r.observed * 1000).toLocaleString()}</td><td>{r.regime}</td><td>{r.deviation?.toFixed(2) ?? 'N/A'}</td><td>{r.score ?? 'N/A'}</td><td>{r.direction || 'none'}</td><td className="p-2 max-w-xs">{r.eligible ? 'Paper eligible' : 'No trade'}: {r.reasons.join('; ')}</td></tr>)}</tbody></table></div>{!state?.latest?.length && <p className="text-slate-400">No observations yet.</p>}</section>
    {analytics && <section className="bg-slate-800 rounded-xl p-4 space-y-3">
      <h2 className="font-semibold">Forward evidence by pair and policy</h2>
      <p className="text-sm text-slate-300">Review each exact account, broker pair, timeframe and paper policy separately. The 300 closed-trade target applies to each row; pooled totals do not qualify a pair.</p>
      <div className="overflow-x-auto"><table className="w-full min-w-[850px] text-sm text-left [&_th]:p-2 [&_td]:p-2">
        <thead><tr><th>Account / pair</th><th>Timeframe</th><th>Policy</th><th>Evaluations</th><th>Closed / 300</th><th>Mean R</th><th>Win rate</th><th>Other states</th></tr></thead>
        <tbody>{(analytics.per_pair_policy || []).map((p: any) => <tr key={`${p.scope}:${p.symbol}:${p.timeframe}:${p.policy_id}`} className="border-t border-slate-700">
          <td>{p.scope} / {p.symbol}{p.research_run_id && <div className="text-xs text-cyan-300">Research {p.research_run_id}</div>}</td>
          <td>{p.timeframe}</td>
          <td><details><summary className="cursor-pointer">{p.policy_id === 'legacy_unknown' ? 'Unknown' : p.policy_id.slice(0, 12)}</summary><p className="break-all text-xs">{p.policy_id}</p><p className="break-all text-xs">Scanner runs: {p.run_ids.join(', ') || 'Unknown'}</p></details></td>
          <td>{p.observations}</td><td>{p.count} / 300 ({p.sample})</td><td>{p.mean_r?.toFixed(2) ?? 'N/A'}</td>
          <td>{p.win_rate == null ? 'N/A' : `${(p.win_rate*100).toFixed(1)}%`}</td>
          <td>Pending {p.states.pending || 0}; Open {p.states.open || 0}; Unresolved {p.states.unresolved || 0}</td>
        </tr>)}</tbody>
      </table></div>
      {!analytics.per_pair_policy?.length && <p className="text-slate-400">No saved pair evidence yet.</p>}
    </section>}
    {analytics && <section className="bg-slate-800 rounded-xl p-4 space-y-3"><h2 className="font-semibold">All scanner evidence</h2><p>{analytics.observations} observations · {analytics.overall.count} closed paper trades across all pairs and policies</p><p className="text-sm text-slate-400">{analytics.model} A large sample alone does not establish an edge.</p><label>Break down by<select className="block bg-slate-900 p-2 rounded" value={group} onChange={e => setGroup(e.target.value)}>{['symbol','scope','policy_id','score_bucket','regime','session','setup','volatility','news'].map(g => <option key={g}>{g}</option>)}</select></label><div className="overflow-x-auto"><table className="w-full min-w-[480px] text-sm text-left [&_th]:p-2 [&_td]:p-2"><thead><tr><th>Group</th><th>Closed</th><th>Mean R</th><th>Win rate</th><th>Evidence</th></tr></thead><tbody>{Object.entries(analytics.groups[group] || {}).map(([k,v]: [string, any]) => <tr key={k}><td>{k}</td><td>{v.count}</td><td>{v.mean_r?.toFixed(2) ?? 'N/A'}</td><td>{v.win_rate == null ? 'N/A' : `${(v.win_rate*100).toFixed(1)}%`}</td><td>{v.sample}</td></tr>)}</tbody></table></div><p className="text-xs text-slate-400">Pending {analytics.states.pending || 0} · Open {analytics.states.open || 0} · Unresolved {analytics.states.unresolved || 0}. Stopping or restarting leaves unfinished outcomes unresolved.</p></section>}
    <section className="bg-slate-800 rounded-xl p-4 space-y-3"><h2 className="font-semibold">Automatic paper ledger</h2><p className="text-sm text-slate-400">Latest 500. Entry uses the first full candle starting after observation, with adverse slippage. If stop and target both occur in a candle, stop wins. One hypothetical position per symbol per scan; missing outcome bars remain unresolved.</p><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-sm text-left"><thead><tr>{['Pair','Side','State','Entry','Stop / target','Outcome R','Exit reason'].map(h => <th className="p-2" key={h}>{h}</th>)}</tr></thead><tbody>{ledger.trades.map((p: any) => <tr key={p.id} className="border-t border-slate-700"><td className="p-2">{p.symbol}</td><td>{p.direction}</td><td>{p.state}</td><td>{p.entry ?? 'Pending'}</td><td>{p.stop ?? '—'} / {p.target ?? '—'}</td><td>{p.r_multiple?.toFixed(2) ?? 'N/A'}</td><td>{p.exit_reason || '—'}</td></tr>)}</tbody></table></div><details><summary>Eligible and rejected signal history ({ledger.observations.length} latest)</summary><ul className="space-y-2 mt-3 text-sm">{ledger.observations.map((r: any, i: number) => <li key={r.id || i} className="break-words">{r.symbol} · {new Date(r.observed*1000).toLocaleString()} · {r.regime} · {r.reasons.join('; ')}</li>)}</ul></details></section>
    <section className="bg-slate-800 rounded-xl p-4 space-y-3" aria-label="Saved scanner evidence">
      <h2 className="font-semibold">Saved evidence</h2>
      <p className="text-sm text-slate-400">Browse older records or download all runs, observations and paper trades. Pages keep a fixed record boundary while new signals arrive; trade outcomes may still update. Downloads capture a consistent snapshot. Exports include broker account identifiers.</p>
      <div className="flex flex-wrap gap-3 items-end">
        <label>Record type<select className="block bg-slate-900 p-2 rounded" value={historyKind} disabled={historyBusy} onChange={e => { setHistoryKind(e.target.value); setHistoryPage(null) }}><option value="observations">Signals and rejections</option><option value="trades">Paper trades</option></select></label>
        <button className={button} disabled={historyBusy} onClick={() => void loadHistory(historyKind)}>Latest records</button>
        <button className={button} disabled={historyBusy || historyPage?.next_before == null} onClick={() => void loadHistory(historyKind, true)}>Older records</button>
        <button className={button} disabled={exportBusy} onClick={() => void exportEvidence()}>{exportBusy ? 'Exporting...' : 'Download all evidence (JSON)'}</button>
      </div>
      {historyPage && <><p className="text-sm">{historyPage.items.length} shown | {historyPage.total} records in this browsing window</p><ul className="space-y-2 text-sm">{historyPage.items.map((r: any) => <li key={r.record_cursor} className="border-t border-slate-700 pt-2 break-words"><details><summary className="cursor-pointer">{r.symbol} | {r.scope || 'Legacy account unknown'} | {new Date(r.observed*1000).toLocaleString()} | {r.state || r.regime}</summary><pre className="whitespace-pre-wrap break-all text-xs mt-2">{JSON.stringify(r, null, 2)}</pre></details></li>)}</ul>{historyPage.items.length === 0 && <p>No saved records for this selection.</p>}</>}
    </section>
  </div>
}

import { useEffect, useState, useCallback } from 'react'
import { Settings as SettingsIcon, Save, RefreshCw, AlertCircle, Link as LinkIcon, CheckCircle2 } from 'lucide-react'
import { authHeaders } from '../api/client'

// Mocking some config fetch since I don't have a specific client function for all config
// But I can see the routes in bot_control.py
const BASE = (import.meta as any).env?.VITE_API_URL ?? ''

interface ConfigItem {
  key: string
  value: string
  value_type: string
  description: string
  updated_at: string
}

interface UserProfile {
  id: number
  email: string
  deriv_connected: boolean
  deriv_account_id: string | null
}

export default function Settings() {
  const [config, setConfig] = useState<ConfigItem[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [saving, setSaving] = useState<string | null>(null)
  
  // Deriv Connection State
  const [user, setUser] = useState<UserProfile | null>(null)
  const [derivKey, setDerivKey] = useState('')
  const [connecting, setConnecting] = useState(false)

  const loadData = useCallback(async () => {
    setLoading(true)
    try {
      const [configRes, userRes] = await Promise.all([
        fetch(`${BASE}/api/config`, { headers: authHeaders() }),
        fetch(`${BASE}/api/users/me`, { headers: authHeaders() })
      ])
      
      if (configRes.ok) {
        const configData = await configRes.json()
        setConfig(configData.config)
      }
      
      if (userRes.ok) {
        const userData = await userRes.json()
        setUser(userData)
      }
      
      setError(null)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadData()
  }, [loadData])

  const handleConnectDeriv = async () => {
    if (!derivKey) return
    setConnecting(true)
    try {
      const res = await fetch(`${BASE}/api/users/me/deriv-connection`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', ...authHeaders() },
        body: JSON.stringify({ api_key: derivKey })
      })
      
      if (!res.ok) {
        const err = await res.json()
        throw new Error(err.detail || 'Failed to connect Deriv')
      }
      
      const data = await res.json()
      alert(`Successfully connected to Deriv account: ${data.account_id}`)
      setDerivKey('')
      loadData()
    } catch (err: any) {
      alert(err.message)
    } finally {
      setConnecting(false)
    }
  }

  const handleUpdate = async (key: string, newValue: string) => {
    setSaving(key)
    try {
      const res = await fetch(`${BASE}/api/config/${key}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', ...authHeaders() },
        body: JSON.stringify({ value: newValue })
      })
      if (!res.ok) {
          const err = await res.json()
          throw new Error(err.detail || 'Update failed')
      }
      // Update local state
      setConfig(prev => prev.map(item => item.key === key ? { ...item, value: newValue } : item))
    } catch (err: any) {
      alert(err.message)
    } finally {
      setSaving(null)
    }
  }

  return (
    <div className="p-4 sm:p-6 space-y-6 max-w-4xl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white">Account Settings</h1>
          <p className="text-slate-400 text-xs sm:text-sm">Manage your profile and broker connections.</p>
        </div>
        <button 
            onClick={() => loadData()}
            className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
        >
            <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4 flex items-center gap-3 text-red-400 text-sm">
          <AlertCircle className="w-5 h-5" />
          {error}
        </div>
      )}

      {/* Deriv Connection Card */}
      <div className="bg-slate-800 border border-slate-700 rounded-xl overflow-hidden">
        <div className="p-4 border-b border-slate-700 bg-slate-900/50 flex items-center justify-between">
            <div className="flex items-center gap-2">
                <LinkIcon className="w-4 h-4 text-cyan-400" />
                <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider">Deriv Broker Connection</h3>
            </div>
            {user?.deriv_connected && (
                <div className="flex items-center gap-1.5 text-[10px] font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
                    <CheckCircle2 className="w-3 h-3" />
                    CONNECTED
                </div>
            )}
        </div>
        <div className="p-6 space-y-4">
            {user?.deriv_connected ? (
                <div className="flex items-center justify-between p-4 bg-slate-900/50 rounded-lg border border-slate-700">
                    <div>
                        <div className="text-xs text-slate-500 uppercase font-bold tracking-tight">Active Account ID</div>
                        <div className="text-lg font-mono text-white">{user.deriv_account_id}</div>
                    </div>
                    <button 
                        onClick={() => {
                            setDerivKey('')
                            setUser(prev => prev ? {...prev, deriv_connected: false} : null)
                        }}
                        className="text-xs text-red-400 hover:text-red-300 font-bold"
                    >
                        Disconnect
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    <p className="text-sm text-slate-400">
                        To connect your Deriv account, go to <a href="https://app.deriv.com/account/api-token" target="_blank" rel="noreferrer" className="text-cyan-400 hover:underline">Deriv API Token settings</a>, create a token with "Read" and "Trade" scopes, then paste it below.
                    </p>
                    <div className="flex gap-2">
                        <input 
                            type="password"
                            placeholder="Paste your Deriv API Token here..."
                            value={derivKey}
                            onChange={(e) => setDerivKey(e.target.value)}
                            className="flex-1 bg-slate-900 border border-slate-700 text-white text-sm rounded-lg px-4 py-2 outline-none focus:border-cyan-500"
                        />
                        <button 
                            onClick={handleConnectDeriv}
                            disabled={connecting || !derivKey}
                            className="bg-cyan-600 hover:bg-cyan-500 disabled:opacity-50 text-white text-sm font-bold px-6 py-2 rounded-lg transition-colors flex items-center gap-2"
                        >
                            {connecting ? <RefreshCw className="w-4 h-4 animate-spin" /> : 'Connect'}
                        </button>
                    </div>
                </div>
            )}
        </div>
      </div>

      <div className="bg-slate-800 border border-slate-700 rounded-xl overflow-hidden">
        <div className="p-4 border-b border-slate-700 bg-slate-900/50">
            <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider">Global System Config</h3>
        </div>
        <div className="divide-y divide-slate-700">
          {config.filter(c => !['DERIV_APP_ID', 'DERIV_API_TOKEN', 'SECRET_KEY', 'DATABASE_URL', 'REDIS_URL'].includes(c.key)).map((item) => (
            <div key={item.key} className="p-4 sm:p-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div className="flex-1">
                <div className="text-sm font-bold text-white mb-1">{item.key}</div>
                <div className="text-[10px] sm:text-xs text-slate-500">{item.description}</div>
              </div>
              <div className="flex items-center gap-3">
                <input 
                    type="text"
                    readOnly
                    defaultValue={item.value}
                    onBlur={(e) => {
                        if (e.target.value !== item.value) {
                            handleUpdate(item.key, e.target.value)
                        }
                    }}
                    className="flex-1 md:flex-none bg-slate-900 border border-slate-700 text-slate-200 text-sm rounded-lg px-3 py-2 outline-none focus:border-cyan-500 w-full md:w-32 font-mono text-right md:text-left"
                />
                {saving === item.key && <RefreshCw className="w-4 h-4 text-cyan-400 animate-spin flex-shrink-0" />}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-slate-800/50 border border-slate-700 border-dashed rounded-xl p-6">
          <div className="flex items-start gap-3">
              <AlertCircle className="w-5 h-5 text-slate-500 mt-0.5" />
              <div>
                  <h4 className="text-sm font-bold text-slate-400">Environment Variables</h4>
                  <p className="text-xs text-slate-500 mt-1">
                      Sensitive keys (API tokens, database URLs) must be configured in the <code className="text-cyan-600 bg-cyan-500/10 px-1 rounded">.env</code> file 
                      and require a service restart to take effect.
                  </p>
              </div>
          </div>
      </div>
    </div>
  )
}

import { useEffect, useState, useCallback } from 'react'
import { Activity, RefreshCw, Zap, TrendingUp, TrendingDown, Info } from 'lucide-react'
import { fetchScanner, fetchSignals, type ScannerRow, type Signal } from '../api/client'
import { format } from 'date-fns'

const scoreColor = (s: number) => s >= 9 ? 'text-yellow-400' : s >= 6 ? 'text-emerald-400' : 'text-slate-400'
const dirColor = (d: string | null) => d === 'buy' ? 'text-emerald-400' : d === 'sell' ? 'text-red-400' : 'text-slate-400'

export default function Signals() {
  const [signals, setSignals] = useState<Signal[]>([])
  const [scanner, setScanner] = useState<ScannerRow[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [firedOnly, setFiredOnly] = useState(false)
  const regimeCounts = scanner.reduce<Record<string, number>>((counts, row) => {
    counts[row.regime] = (counts[row.regime] || 0) + 1
    return counts
  }, {})

  const loadSignals = useCallback(async () => {
    setLoading(true)
    try {
      const [res, scan] = await Promise.all([fetchSignals({
        limit: 50,
        fired: firedOnly ? true : undefined
      }), fetchScanner()])
      setSignals(res.signals)
      setScanner(scan.scanner)
      setError(null)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }, [firedOnly])

  useEffect(() => {
    loadSignals()
    const timer = setInterval(loadSignals, 30000) // Auto-refresh every 30s
    return () => clearInterval(timer)
  }, [loadSignals])

  return (
    <div className="p-4 sm:p-6 space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white">Signal Feed</h1>
          <p className="text-slate-400 text-xs sm:text-sm">Real-time market analysis and strategy evaluations</p>
        </div>
        <div className="flex items-center gap-3">
            <button 
                onClick={() => setFiredOnly(!firedOnly)}
                className={`flex-1 sm:flex-none px-3 py-1.5 rounded-lg text-xs font-semibold transition-colors ${
                    firedOnly ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30' : 'bg-slate-800 text-slate-400 border border-slate-700'
                }`}
            >
                {firedOnly ? 'Fired Only' : 'All Evaluations'}
            </button>
            <button 
                onClick={() => loadSignals()}
                className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
            >
                <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
            </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4 text-red-400 text-sm">
          Failed to load signals: {error}
        </div>
      )}

      <div className="grid gap-4">
        <section className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3" aria-label="Regime and confluence summary">
          {['mean_reverting', 'trending', 'mixed'].map(regime => <div key={regime} className="bg-slate-800 border border-slate-700 rounded-xl p-4"><p className="text-xs text-slate-500 uppercase">{regime.replace('_', ' ')}</p><p className="text-2xl font-bold text-white">{regimeCounts[regime] || 0}</p><p className="text-xs text-slate-400">latest markets</p></div>)}
          <div className="bg-slate-800 border border-cyan-800 rounded-xl p-4"><p className="text-xs text-cyan-300 uppercase">High confluence</p><p className="text-2xl font-bold text-cyan-300">{scanner.filter(row => row.score >= 9).length}</p><p className="text-xs text-slate-400">score 9+; not a probability</p></div>
        </section>
        <section className="bg-slate-800 border border-slate-700 rounded-xl p-4 overflow-x-auto" aria-label="Unified market scanner">
          <div className="flex items-center justify-between mb-3"><h2 className="font-semibold text-white">Unified market scanner</h2><span className="text-xs text-slate-500">Latest stored evaluation per symbol/timeframe</span></div>
          <table className="w-full text-sm min-w-[760px]"><thead><tr className="text-left text-slate-500"><th className="p-2">Market</th><th>Regime</th><th>Deviation</th><th>Score</th><th>State</th><th>Age</th><th>Reason</th></tr></thead><tbody>{scanner.map(row => <tr key={`${row.symbol}-${row.timeframe}`} className="border-t border-slate-700"><td className="p-2 font-semibold">{row.symbol} <span className="text-xs text-slate-500">{row.timeframe}</span></td><td className="text-slate-300">{row.regime}</td><td className={row.z_score !== null && Math.abs(row.z_score) >= 2 ? 'text-cyan-300' : 'text-slate-300'}>{row.z_score?.toFixed(2) ?? 'N/A'}</td><td className={scoreColor(row.score)}>{row.score}</td><td className={row.fired ? 'text-emerald-300' : 'text-slate-400'}>{row.fired ? row.direction?.toUpperCase() : 'AVOID'}</td><td className="text-slate-400">{row.age_seconds}s</td><td className="text-slate-400">{row.reason}</td></tr>)}</tbody></table>{!scanner.length && !loading && <p className="text-slate-500 py-4">No stored scanner evaluations yet.</p>}
        </section>
        {signals.length === 0 && !loading ? (
          <div className="bg-slate-800 border border-slate-700 rounded-xl p-12 text-center text-slate-500">
            No signals found
          </div>
        ) : (
          signals.map((s) => (
            <div key={s.id} className="bg-slate-800 border border-slate-700 rounded-xl p-4 hover:border-slate-600 transition-colors">
              <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-lg ${s.fired ? 'bg-cyan-500/20' : 'bg-slate-700/50'}`}>
                    <Activity className={`w-5 h-5 ${s.fired ? 'text-cyan-400' : 'text-slate-400'}`} />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-bold text-white">{s.symbol}</span>
                      <span className="text-xs text-slate-500 uppercase">{s.timeframe}</span>
                    </div>
                    <div className="text-xs text-slate-400">
                      {format(new Date(s.evaluated_at), 'HH:mm:ss · MMM dd, yyyy')}
                    </div>
                  </div>
                </div>
                <div className="text-right">
                  <div className={`text-xl font-mono font-bold ${scoreColor(s.score)}`}>
                    {s.score}/10
                  </div>
                  <div className="text-[10px] text-slate-500 uppercase tracking-wider font-semibold">
                    Confluence
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-2 sm:gap-4 mb-4">
                <Indicator 
                    label="Z-Score" 
                    value={s.indicators.z_score?.toFixed(2)} 
                    accent={Math.abs(s.indicators.z_score || 0) > 2} 
                />
                <Indicator 
                    label="RSI" 
                    value={s.indicators.rsi?.toFixed(0)} 
                    accent={(s.indicators.rsi || 50) > 70 || (s.indicators.rsi || 50) < 30} 
                />
                <Indicator 
                    label="Stoch K" 
                    value={s.indicators.stoch_k?.toFixed(0)} 
                />
                <Indicator 
                    label="Hurst" 
                    value={s.indicators.hurst?.toFixed(2)} 
                    accent={(s.indicators.hurst || 0.5) > 0.6} 
                />
                <Indicator 
                    label="LSL Grab" 
                    value={s.indicators.lsl_grab ? 'YES' : 'NO'} 
                    accent={s.indicators.lsl_grab} 
                />
                <Indicator 
                    label="BOS/CH" 
                    value={s.indicators.bos_choch ? 'YES' : 'NO'} 
                    accent={s.indicators.bos_choch} 
                />
                <Indicator 
                    label="OB" 
                    value={s.indicators.order_block ? 'YES' : 'NO'} 
                    accent={s.indicators.order_block} 
                />
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-slate-700/50">
                <div className="flex items-center gap-2 text-sm">
                   {s.direction && (
                       <span className={`flex items-center gap-1 font-bold uppercase text-xs ${dirColor(s.direction)}`}>
                           {s.direction === 'buy' ? <TrendingUp className="w-3 h-3"/> : <TrendingDown className="w-3 h-3"/>}
                           {s.direction}
                       </span>
                   )}
                   <span className="text-slate-400 text-xs italic">{s.reason}</span>
                </div>
                {s.fired && (
                    <span className="flex items-center gap-1 px-2 py-0.5 bg-emerald-500/10 text-emerald-400 text-[10px] font-bold uppercase rounded">
                        <Zap className="w-3 h-3" /> Fired
                    </span>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  )
}

function Indicator({ label, value, accent }: { label: string, value: string | undefined, accent?: boolean }) {
    return (
        <div className="bg-slate-900/30 rounded px-2 py-1 border border-slate-700/30">
            <div className="text-[9px] text-slate-500 uppercase font-bold truncate">{label}</div>
            <div className={`text-xs font-mono ${accent ? 'text-cyan-400' : 'text-slate-300'}`}>{value || '—'}</div>
        </div>
    )
}

import { useEffect, useState, useCallback } from 'react'
import { TrendingUp, TrendingDown, RefreshCw, Filter, ExternalLink } from 'lucide-react'
import { fetchTrades, type Trade } from '../api/client'
import { format } from 'date-fns'

const pnlColor  = (v: number | null) => {
  if (v === null) return 'text-slate-400'
  return v >= 0 ? 'text-emerald-400' : 'text-red-400'
}
const dirBg = (d: string) => d === 'buy' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'
const statusBg = (s: string) => {
  switch (s) {
    case 'open': return 'bg-cyan-500/20 text-cyan-400'
    case 'closed': return 'bg-slate-700 text-slate-300'
    case 'pending': return 'bg-yellow-500/20 text-yellow-400'
    default: return 'bg-slate-800 text-slate-500'
  }
}

export default function Trades() {
  const [trades, setTrades] = useState<Trade[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [page, setPage] = useState(1)
  const [total, setTotal] = useState(0)
  const [statusFilter, setStatusFilter] = useState<string>('')

  const loadTrades = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetchTrades({ 
        page, 
        page_size: 20,
        status: statusFilter || undefined
      })
      setTrades(res.trades)
      setTotal(res.total)
      setError(null)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }, [page, statusFilter])

  useEffect(() => {
    loadTrades()
  }, [loadTrades])

  return (
    <div className="p-4 sm:p-6 space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-white">Trade History</h1>
          <p className="text-slate-400 text-xs sm:text-sm">Review all executed and pending orders</p>
        </div>
        <div className="flex items-center gap-3">
            <select 
                value={statusFilter}
                onChange={(e) => { setStatusFilter(e.target.value); setPage(1); }}
                className="flex-1 sm:flex-none bg-slate-800 border border-slate-700 text-slate-200 text-sm rounded-lg px-3 py-2 outline-none focus:border-cyan-500"
            >
                <option value="">All Status</option>
                <option value="open">Open</option>
                <option value="closed">Closed</option>
                <option value="pending">Pending</option>
            </select>
            <button 
                onClick={() => loadTrades()}
                className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
                title="Refresh"
            >
                <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
            </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4 flex items-center gap-3 text-red-400">
          <p className="text-sm">Failed to load trades: {error}</p>
        </div>
      )}

      <div className="bg-slate-800 border border-slate-700 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-900/50 text-slate-400 uppercase text-[10px] tracking-wider">
              <tr>
                <th className="px-6 py-4 font-semibold">Asset / Time</th>
                <th className="px-6 py-4 font-semibold">Direction</th>
                <th className="px-6 py-4 font-semibold">Entry / Exit</th>
                <th className="px-6 py-4 font-semibold">SL / TP</th>
                <th className="px-6 py-4 font-semibold">Stake</th>
                <th className="px-6 py-4 font-semibold">PnL</th>
                <th className="px-6 py-4 font-semibold">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-700">
              {trades.length === 0 && !loading ? (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-slate-500">
                    No trades found
                  </td>
                </tr>
              ) : (
                trades.map((t) => (
                  <tr key={t.trade_id} className="hover:bg-slate-700/30 transition-colors">
                    <td className="px-6 py-4">
                      <div className="font-medium text-white">{t.symbol}</div>
                      <div className="text-xs text-slate-500">{format(new Date(t.opened_at), 'MMM dd, HH:mm')}</div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${dirBg(t.direction)}`}>
                        {t.direction}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-white font-mono">{t.entry_price.toFixed(2)}</div>
                      <div className="text-xs text-slate-500 font-mono">{t.exit_price?.toFixed(2) || '—'}</div>
                    </td>
                    <td className="px-6 py-4 text-xs font-mono">
                      <div className="text-red-400/80">{t.stop_loss.toFixed(2)}</div>
                      <div className="text-emerald-400/80">{t.take_profit.toFixed(2)}</div>
                    </td>
                    <td className="px-6 py-4 text-white font-medium">
                      ${t.stake.toFixed(2)}
                    </td>
                    <td className={`px-6 py-4 font-bold ${pnlColor(t.pnl)}`}>
                      {t.pnl !== null ? `${t.pnl >= 0 ? '+' : ''}${t.pnl.toFixed(2)}` : '—'}
                      {t.pnl_pct !== null && (
                        <span className="text-[10px] ml-1 opacity-70">
                          ({t.pnl_pct.toFixed(1)}%)
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] font-semibold uppercase ${statusBg(t.status)}`}>
                        {t.status}
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Pagination */}
      {total > 0 && (
          <div className="flex items-center justify-between text-sm text-slate-400">
              <p>Showing {trades.length} of {total} trades</p>
              <div className="flex gap-2">
                  <button 
                    disabled={page === 1}
                    onClick={() => setPage(p => p - 1)}
                    className="px-3 py-1 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 disabled:opacity-50 transition-colors"
                  >
                      Prev
                  </button>
                  <button 
                    disabled={trades.length < 20}
                    onClick={() => setPage(p => p + 1)}
                    className="px-3 py-1 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 disabled:opacity-50 transition-colors"
                  >
                      Next
                  </button>
              </div>
          </div>
      )}
    </div>
  )
}
